 const items=financeCharges.filter(c=>c.student_id===p.student.id),summary=financeSummary(items);const message={none:['Sem cobranças cadastradas','Nenhuma cobrança ativa foi cadastrada para você.'],late:['Há pagamentos em atraso',summary.overdue.length+' cobrança(s) com vencimento anterior a hoje.'],today:['Seu pagamento vence hoje','Não há cobranças vencidas, mas existe um vencimento para hoje.'],current:['Você está em dia','Não há pagamentos vencidos nos seus registros.']}[summary.status];
 return heading('Meu financeiro','Consulte seus pagamentos, pendências e próximos vencimentos.')+`<section class="finance-overview ${summary.status==='late'?'has-overdue':''}"><span class="finance-overview-icon">${icon(summary.status==='current'?'check':'wallet')}</span><div><span class="eyebrow">MINHA SITUAÇÃO</span><h2>${message[0]}</h2><p>${message[1]}</p></div><span class="pill">${esc(p.class_name)}</span></section><section class="stats finance-stats"><article class="stat"><div class="stat-head">Próximo vencimento<span class="stat-icon">${icon('check')}</span></div><strong class="finance-date">${summary.next?date(summary.next.due_date):'—'}</strong><small>${summary.next?formatMoney(summary.next.amount_cents)+' · '+esc(summary.next.description):'Nenhum próximo vencimento cadastrado'}</small></article>${stat('Total em aberto',formatMoney(summary.openCents),'Inclui vencimentos futuros e pendências','wallet')}${stat('Em atraso',formatMoney(summary.overdueCents),summary.overdue.length+' cobrança(s) vencida(s)','grades')}${stat('Pagamentos confirmados',formatMoney(summary.paidCents),'Confirmações feitas pela coordenação','check')}</section><section class="panel"><div class="panel-header"><h2>Minhas cobranças</h2><span class="pill">${items.length} registros</span></div>${items.length?`<div class="table-wrap"><table class="finance-table learner-finance-table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Pagamento</th></tr></thead><tbody>${sortedCharges(items).map(c=>`<tr><td><strong>${esc(c.description)}</strong><div class="finance-mobile-detail">${chargePill(c)}${c.state==='paid'?`<span class="finance-method">Pago em ${date(c.paid_on)} · ${paymentMethods[c.payment_method]||'Outro'}</span>`:''}</div></td><td>${date(c.due_date)}</td><td class="finance-amount">${formatMoney(c.amount_cents)}</td><td>${chargePill(c)}</td><td>${c.state==='paid'?`${date(c.paid_on)}<span class="finance-method">${paymentMethods[c.payment_method]||'Outro'}</span>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma cobrança por enquanto','Os valores e os vencimentos aparecerão aqui quando forem cadastrados pela coordenação.','','','wallet')}</section>`;
