function bindFinance(){if($('#finance-student-filter'))$('#finance-student-filter').onchange=e=>{financeStudentFilter=e.target.value;render()};if($('#finance-status-filter'))$('#finance-status-filter').onchange=e=>{financeStatusFilter=e.target.value;render()}}
async function persistLocalFinance(charges){if(localStorage.getItem(FINANCE_KEY)!==financeSnapshot)throw Error('As cobranças foram alteradas em outra janela. Atualize antes de salvar.');const raw=JSON.stringify(charges);localStorage.setItem(FINANCE_KEY,raw);financeSnapshot=raw;financeCharges=charges}
async function changeCharge(c,fields){
 if(appRole!=='coordinator')throw Error('Somente a coordenação pode alterar cobranças.');
 if(local()){const current=financeCharges.find(x=>x.id===c.id);if(!current||current.row_version!==c.row_version)throw Error('A cobrança foi alterada. Atualize os dados.');await persistLocalFinance(financeCharges.map(x=>x.id===c.id?{...x,...fields,row_version:x.row_version+1,updated_at:new Date().toISOString()}:x));return}
 const {data,error}=await client.from('school_finance_charges').update({...fields,row_version:c.row_version+1}).eq('id',c.id).eq('workspace_owner_id',workspaceId).eq('row_version',c.row_version).select('id,row_version').maybeSingle();if(error)throw error;if(!data)throw Error('Outro coordenador alterou esta cobrança. Atualize os dados antes de tentar novamente.');await loadFinance();
}
function editCharge(id){
 if(appRole!=='coordinator')return;if(!local()&&!financeReady){toast('Recurso indisponível. Atualize os dados e tente novamente.');return}const c=financeCharges.find(x=>x.id===id);if(c&&c.state!=='open'){toast('Apenas cobranças em aberto podem ser editadas.');return}if(!c&&!state.students.length){toast('Cadastre um aluno antes de criar a cobrança.');return}
 modal(c?'Editar cobrança':'Nova cobrança','O valor e o vencimento ficarão visíveis para o aluno vinculado.',`<div class="form-grid">${c?`<div class="full finance-student-caption"><span class="small muted">Aluno</span><strong>${esc(chargeStudentName(c))}</strong></div>`:`<label class="full">Aluno<select name="student_id" required>${options(state.students,financeStudentFilter)}</select></label>`}<label class="full">Descrição<input name="description" required maxlength="160" placeholder="Ex.: Mensalidade — novembro" value="${esc(c?.description||'')}"></label><label>Valor (R$)<input name="amount" required inputmode="decimal" placeholder="0,00" value="${c?Math.floor(c.amount_cents/100)+','+String(c.amount_cents%100).padStart(2,'0'):''}"></label><label>Vencimento<input name="due_date" type="date" required value="${c?.due_date||financeToday()}"></label></div>`,async values=>{if(busy)return;const description=values.description.trim();if(!description)throw Error('Informe a descrição.');const fields={description,amount_cents:parseChargeAmount(values.amount),due_date:values.due_date};if(!/^\d{4}-\d{2}-\d{2}$/.test(fields.due_date))throw Error('Escolha um vencimento válido.');const student=c?null:state.students.find(s=>s.id===values.student_id);if(!c&&!student)throw Error('Selecione um aluno válido.');busy=true;try{if(c)await changeCharge(c,fields);else if(local()){await persistLocalFinance([{id:uid(),workspace_owner_id:'local',student_id:student.id,student_name:student.name,...fields,state:'open',paid_on:null,payment_method:null,row_version:1,created_at:new Date().toISOString(),updated_at:new Date().toISOString()},...financeCharges])}else{const r=await client.from('school_finance_charges').insert({workspace_owner_id:workspaceId,student_id:student.id,...fields}).select('id').single();if(r.error)throw r.error;await loadFinance()}$('#modal').close();render();toast(c?'Cobrança atualizada.':'Cobrança cadastrada.')}finally{busy=false}})
}
function payCharge(id){const c=financeCharges.find(c=>c.id===id);if(!c||c.state!=='open'||appRole!=='coordinator')return;modal('Registrar pagamento','Confirme somente após conferir o recebimento.',`<div class="payment-summary"><strong>${esc(chargeStudentName(c))}</strong><span>${esc(c.description)}</span><b>${formatMoney(c.amount_cents)}</b><small>Vencimento: ${date(c.due_date)}</small></div><div class="form-grid"><label>Data do pagamento<input name="paid_on" type="date" required max="${financeToday()}" value="${financeToday()}"></label><label>Forma de pagamento<select name="payment_method" required>${Object.entries(paymentMethods).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label></div>`,async values=>{if(busy)return;if(!values.paid_on||values.paid_on>financeToday())throw Error('Informe uma data de pagamento até hoje.');if(!paymentMethods[values.payment_method])throw Error('Selecione a forma de pagamento.');busy=true;try{await changeCharge(c,{state:'paid',paid_on:values.paid_on,payment_method:values.payment_method});$('#modal').close();render();toast('Pagamento confirmado. O aluno já pode consultar a atualização.')}finally{busy=false}})}
function confirmFinanceChange(id,reopen){const c=financeCharges.find(c=>c.id===id);if(!c||appRole!=='coordinator'||(reopen?c.state!=='paid':c.state!=='open'))return;confirmDialog(reopen?'Reabrir esta cobrança?':'Cancelar esta cobrança?',reopen?'O pagamento deixará de ser considerado confirmado e a cobrança voltará a ficar em aberto. Use esta opção para corrigir um registro incorreto.':'A cobrança deixará de contar como pendência e continuará visível no histórico como cancelada.',async()=>{if(busy)return;busy=true;try{await changeCharge(c,{state:reopen?'open':'canceled',paid_on:null,payment_method:null});$('#modal').close();render();toast(reopen?'Cobrança reaberta.':'Cobrança cancelada.')}catch(e){toast(friendly(e))}finally{busy=false}})}
async function financeAudit(id){if(local()||appRole!=='coordinator')return;try{const r=await client.from('school_finance_audit').select('actor_id,operation,previous_data,current_data,changed_at').eq('workspace_owner_id',workspaceId).eq('charge_id',id).order('changed_at',{ascending:false});if(r.error)throw r.error;const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Histórico da cobrança</h2><p>Registro das alterações realizadas pela coordenação.</p>${r.data.map(a=>{const old=a.previous_data,next=a.current_data,label=!old?'Cobrança criada':next.state==='paid'?'Pagamento confirmado':next.state==='canceled'?'Cobrança cancelada':old.state==='paid'?'Pagamento reaberto':'Cobrança atualizada';return `<article class="submission-card"><strong>${label}</strong><p>${formatMoney(next.amount_cents)} · vencimento ${date(next.due_date)}</p><small class="muted">${new Date(a.changed_at).toLocaleString('pt-BR')} · ${esc(teamMembers.find(m=>m.user_id===a.actor_id)?.display_name||'Coordenação')}</small></article>`}).join('')||'<p>Nenhuma alteração registrada.</p>'}`;d.querySelector('.close').onclick=()=>d.close();d.showModal()}catch(e){toast(friendly(e))}}
function exportFinance(){const quote=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-\t\r]/,"'$&")+'"';const rows=[['Aluno','Descrição','Valor (R$)','Vencimento','Situação','Data do pagamento','Forma de pagamento'],...financeCharges.filter(c=>!financeStudentFilter||c.student_id===financeStudentFilter).map(c=>[chargeStudentName(c),c.description,(c.amount_cents/100).toFixed(2).replace('.',','),date(c.due_date),financeLabels[chargeStatus(c)],c.paid_on?date(c.paid_on):'',paymentMethods[c.payment_method]||''])];download('financeiro-trilha-'+financeToday()+'.csv','\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function handleFinanceAction(action){const [verb,id]=action.split(':');if(!verb.startsWith('finance-'))return false;if(appRole!=='coordinator')return true;if(verb==='finance-new'||verb==='finance-edit')guardNavigation(()=>editCharge(id));else if(verb==='finance-pay')payCharge(id);else if(verb==='finance-cancel')confirmFinanceChange(id,false);else if(verb==='finance-reopen')confirmFinanceChange(id,true);else if(verb==='finance-audit')await financeAudit(id);else if(verb==='finance-export')exportFinance();else if(verb==='finance-sql'){try{const r=await fetch('./finance.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-financeiro.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}}return true}

icons.trophy='<path d="M8 3h8v6a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v6m-4 2h8m-9-2h10"/>';
let quizReady=false,quizItems=[],quizRanking=null,quizLoadError='',quizClass='',quizSelectedWeek=quizWeek(),quizEditorQuestions=[],quizLocalSnapshot=null;
const QUIZ_LOCAL_KEY='trilha-quizzes-v1';
function resetQuizzes(){quizReady=false;quizItems=[];quizRanking=null;quizLoadError='';quizClass='';quizSelectedWeek=quizWeek();quizEditorQuestions=[];quizLocalSnapshot=null}
function quizSelectedClass(){if(appRole==='student'||studentPreview)return currentPortal()?.student.classId||'';if(!state.classes.some(c=>c.id===quizClass))quizClass=state.classes[0]?.id||'';return quizClass}
async function loadQuizRanking(){quizRanking=null;if(local()||!quizReady||!quizSelectedClass())return;const r=await client.rpc('school_weekly_quiz_ranking',{workspace_id:workspaceId,requested_week:quizSelectedWeek,requested_class:quizSelectedClass()});if(r.error){quizLoadError=friendly(databaseFailure(r.error,'consultar o ranking da turma'));return}quizRanking=r.data}
async function loadQuizzes(){quizReady=false;quizItems=[];quizRanking=null;quizLoadError='';if(local()){quizLocalSnapshot=localStorage.getItem(QUIZ_LOCAL_KEY);try{quizItems=JSON.parse(quizLocalSnapshot||'[]')}catch{quizItems=[]}return}if(!workspaceId||appRole==='pending')return;try{if(appRole==='student'){const r=await client.rpc('school_my_quizzes',{workspace_id:workspaceId});if(r.error)throw r.error;quizItems=r.data||[]}else{const r=await client.from('school_quizzes').select('*').eq('workspace_owner_id',workspaceId).order('week_start',{ascending:false});if(r.error)throw r.error;quizItems=r.data||[]}quizReady=true;await loadQuizRanking()}catch(e){if(!schemaMissing(e))quizLoadError=friendly(databaseFailure(e,'consultar os quizzes'));quizReady=false}}
function quizScheduleCaption(q){const fmt=value=>new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});return q.opens_at||q.closes_at?`<p class="quiz-schedule-caption small muted">${q.opens_at?'Abre em '+fmt(q.opens_at):'Abre no início da semana'}<br>${q.closes_at?'Encerra em '+fmt(q.closes_at):'Encerra no fim da semana'} · São Paulo</p>`:''}
function quizStudentItems(p){if(appRole==='student')return quizItems;return quizItems.filter(q=>q.class_id===p.student.classId&&q.published&&q.week_start<=quizWeek()).map(q=>({id:q.id,title:q.title,description:q.description,week_start:q.week_start,question_count:q.questions.length,opens_at:q.opens_at,closes_at:q.closes_at,can_submit:false,result:null}))}
function quizRankingPanel(){return `<section class="panel quiz-ranking-panel"><div class="panel-header"><h2>${icon('trophy')}Ranking semanal da turma</h2><span class="pill">${quizRanking?.entries?.length||0} participantes</span></div><div class="quiz-ranking-caption">${date(quizSelectedWeek)} a ${date(quizWeekEnd(quizSelectedWeek))}</div>${quizLoadError?`<div class="note warn" role="alert">${esc(quizLoadError)}</div>`:''}${quizRanking?.entries?.length?`<div class="table-wrap"><table><thead><tr><th>Posição</th><th>Aluno</th><th>Acertos</th><th>Quizzes</th></tr></thead><tbody>${quizRanking.entries.map(r=>`<tr class="${r.is_me?'quiz-my-rank':''}"><td><span class="quiz-rank-number">${r.position<=3?['🥇','🥈','🥉'][r.position-1]+' ':''}${r.position}º</span></td><td><strong>${esc(r.name)}</strong>${r.is_me?'<span class="pill">Você</span>':''}</td><td><strong>${r.correct_count}</strong><span class="small muted"> / ${r.question_count}</span></td><td>${r.quiz_count}</td></tr>`).join('')}</tbody></table></div>`:empty('A semana está começando',local()?'O ranking real fica disponível após conectar o Supabase.':'As primeiras participações finalizadas aparecerão aqui.','','','trophy')}</section>`}
function quizWeekControl(student=false){return `<label class="quiz-week-label">Semana<input id="quiz-week-filter" type="date" value="${quizSelectedWeek}" ${student?`max="${quizWeek()}"`:''}><span class="field-help">De segunda a domingo · horário de São Paulo</span></label><div class="actions quiz-week-nav">${btn('Semana anterior','quiz-week-prev','secondary','arrow')}${student&&quizSelectedWeek>=quizWeek()?'':btn('Próxima semana','quiz-week-next','secondary','arrow')}</div>`}
function learnerQuizPage(p){if(!quizReady&&!local())return heading('Quiz e ranking','Responda dentro do app e acompanhe sua turma.')+`<section class="panel">${empty('Os quizzes chegam por aqui',quizLoadError||'A coordenação está preparando os quizzes e o ranking da turma.','','','trophy')}</section>`;const items=quizStudentItems(p).filter(q=>q.week_start===quizSelectedWeek);return heading('Quiz da semana','Teste o que aprendeu e acompanhe o ranking da sua turma.')+`<div class="toolbar quiz-filters">${quizWeekControl(true)}<span class="pill">${esc(p.class_name)}</span></div><div class="quiz-student-layout"><section><div class="learning-grid quiz-cards">${items.length?items.map(q=>`<article class="learning-card"><div class="learning-card-top"><span class="learning-type">${icon('book')}${q.question_count} questões</span><span class="pill">${q.result?'Finalizado':studentPreview?'Prévia':q.availability==='scheduled'?'Agendado':q.can_submit?'Aberto':'Encerrado'}</span></div><h3>${esc(q.title)}</h3><p>${esc(q.description||'Responda às perguntas preparadas pela coordenação.')}</p>${quizScheduleCaption(q)}${q.result?`<div class="quiz-card-score">${q.result.correct_count}<span> / ${q.result.question_count} acertos</span></div>`:''}<div class="learning-card-footer"><span class="small muted">1 tentativa oficial</span>${q.availability==='scheduled'&&!q.result&&!studentPreview?'<span class="pill">Aguarde a abertura</span>':btn(q.result?'Ver resultado':studentPreview?'Abrir prévia':q.can_submit?'Responder quiz':'Ver quiz','quiz-open:'+q.id,'','arrow')}${q.result&&!studentPreview?btn('Refazer para estudar','quiz-practice:'+q.id,'secondary','refresh'):''}</div></article>`).join(''):`<section class="panel">${empty('Nenhum quiz nesta semana','Os quizzes publicados para sua turma aparecerão aqui.','','','book')}</section>`}</div></section>${quizRankingPanel()}</div>`}
function quizAdminPage(){quizSelectedClass();const items=quizItems.filter(q=>q.class_id===quizClass&&q.week_start===quizSelectedWeek);return heading('Quizzes','Crie as questões dentro do app e acompanhe os acertos da turma.',btn('Novo quiz','quiz-new','','plus'))+`<div class="toolbar quiz-filters"><label>Turma<select id="quiz-class-filter">${options(state.classes,quizClass,'Selecione uma turma')}</select></label>${quizWeekControl()}</div><div class="quiz-admin-layout"><section class="panel"><div class="panel-header"><h2>Quizzes da semana</h2><span class="pill">${items.length} quizzes</span></div>${items.length?items.map(q=>`<article class="admin-learning-item quiz-admin-item"><div><div class="actions"><span class="pill">${q.published?(q.opens_at&&new Date(q.opens_at)>new Date()?'Agendado':q.closes_at&&new Date(q.closes_at)<=new Date()?'Prazo encerrado':'Publicado'):q.published_at?'Encerrado':'Rascunho'}</span><span class="pill">${q.questions.length} questões</span></div><h3>${esc(q.title)}</h3><p class="small muted">${date(q.week_start)} a ${date(quizWeekEnd(q.week_start))}</p>${quizScheduleCaption(q)}</div><div class="actions">${q.published_at?btn('Resultados','quiz-results:'+q.id,'secondary','chart'):''}${btn('Prévia','quiz-open:'+q.id,'secondary','book')}${iconBtn('Editar quiz','quiz-edit:'+q.id,'edit')}${btn('Criar cópia','quiz-copy:'+q.id,'secondary','plus')}${q.published_at?btn(q.published?'Encerrar':'Reabrir','quiz-toggle:'+q.id,'secondary','check'):iconBtn('Excluir rascunho','quiz-delete:'+q.id,'trash')}</div></article>`).join(''):empty('Seu quiz começa aqui','','quiz-new','Criar quiz','book')}</section>${quizRankingPanel()}</div>`}
function bindQuizzes(){if($('#quiz-class-filter'))$('#quiz-class-filter').onchange=async e=>{quizClass=e.target.value;await loadQuizRanking();render()};if($('#quiz-week-filter'))$('#quiz-week-filter').onchange=async e=>{if(!e.target.value)return;quizSelectedWeek=quizWeek(e.target.value);if(appRole==='student'&&quizSelectedWeek>quizWeek()){quizSelectedWeek=quizWeek()}await loadQuizRanking();render()}}
function blankQuizQuestion(){return {id:uid(),prompt:'',options:Array.from({length:4},()=>({id:uid(),text:''})),correct_option_id:'',explanation:''}}
function readQuizEditor(){const cards=$$('#quiz-question-editor [data-question]');return cards.map(card=>({id:card.dataset.question,prompt:card.querySelector('[data-prompt]').value.trim(),options:[...card.querySelectorAll('[data-option]')].map(o=>({id:o.dataset.option,text:o.querySelector('input').value.trim()})),correct_option_id:card.querySelector('[data-correct]').value,explanation:card.querySelector('[data-explanation]').value.trim()}))}
function paintQuizQuestions(locked=false){$('#quiz-question-editor').innerHTML=quizEditorQuestions.map((q,index)=>`<section class="quiz-question-editor" data-question="${esc(q.id)}"><div class="quiz-question-heading"><h3>Questão ${index+1}</h3>${locked?'':`<button type="button" class="btn text" data-remove-question="${index}">Remover questão</button>`}</div><label>Enunciado<textarea data-prompt required maxlength="2000" ${locked?'disabled':''} placeholder="Escreva a pergunta…">${esc(q.prompt)}</textarea></label><div class="quiz-options-editor">${q.options.map((o,i)=>`<div data-option="${esc(o.id)}"><span>${String.fromCharCode(65+i)}</span><input required maxlength="1000" aria-label="Alternativa ${String.fromCharCode(65+i)} da questão ${index+1}" value="${esc(o.text)}" ${locked?'disabled':''}>${!locked&&q.options.length>2?`<button type="button" class="icon-btn" data-remove-option="${index}:${i}" aria-label="Remover alternativa ${String.fromCharCode(65+i)}">×</button>`:''}</div>`).join('')}</div>${!locked&&q.options.length<6?`<button type="button" class="btn secondary" data-add-option="${index}">${icon('plus')}Adicionar alternativa</button>`:''}<div class="form-grid" style="margin-top:20px"><label>Resposta correta<select data-correct required ${locked?'disabled':''}><option value="">Selecione</option>${q.options.map((o,i)=>`<option value="${esc(o.id)}" ${o.id===q.correct_option_id?'selected':''}>Alternativa ${String.fromCharCode(65+i)}</option>`).join('')}</select></label><label>Explicação <span class="field-help">Opcional · exibida após finalizar</span><textarea data-explanation maxlength="3000" ${locked?'disabled':''}>${esc(q.explanation||'')}</textarea></label></div></section>`).join('');if(locked)return;$$('[data-remove-question]').forEach(b=>b.onclick=()=>{if(quizEditorQuestions.length===1){toast('Mantenha pelo menos uma questão.');return}quizEditorQuestions=readQuizEditor();quizEditorQuestions.splice(Number(b.dataset.removeQuestion),1);paintQuizQuestions()});$$('[data-add-option]').forEach(b=>b.onclick=()=>{quizEditorQuestions=readQuizEditor();quizEditorQuestions[Number(b.dataset.addOption)].options.push({id:uid(),text:''});paintQuizQuestions()});$$('[data-remove-option]').forEach(b=>b.onclick=()=>{quizEditorQuestions=readQuizEditor();const [i,j]=b.dataset.removeOption.split(':').map(Number);const removed=quizEditorQuestions[i].options.splice(j,1)[0];if(quizEditorQuestions[i].correct_option_id===removed.id)quizEditorQuestions[i].correct_option_id='';paintQuizQuestions()})}
async function persistLocalQuizzes(items){if(localStorage.getItem(QUIZ_LOCAL_KEY)!==quizLocalSnapshot)throw Error('Os quizzes foram alterados em outra janela. Atualize antes de salvar.');quizLocalSnapshot=JSON.stringify(items);localStorage.setItem(QUIZ_LOCAL_KEY,quizLocalSnapshot);quizItems=items}
function editQuiz(id,copy=false){if(!local()&&!quizReady){toast('Recurso indisponível. Atualize os dados e tente novamente.');return}if(!state.classes.length){toast('Cadastre uma turma antes de criar o quiz.');return}const source=quizItems.find(q=>q.id===id),quiz=copy?{...clone(source),id:null,published:false,published_at:null,week_start:quizSelectedWeek,opens_at:null,closes_at:null,title:(source.title+' — cópia').slice(0,120)}:source||{},locked=!!quiz.published_at;quizEditorQuestions=clone(quiz.questions||[blankQuizQuestion()]);const d=$('#modal');d.classList.add('quiz-dialog');modal(copy?'Criar cópia do quiz':quiz.id?'Editar quiz':'Novo quiz','Perguntas e alternativas criadas aqui mesmo, sem ferramenta externa.',`<div class="form-grid"><label class="full">Título do quiz<input name="title" required maxlength="120" value="${esc(quiz.title||'')}" placeholder="Ex.: Fundamentos da fé — semana 1"></label><label>Turma<select name="class_id" required ${locked?'disabled':''}>${options(state.classes,quiz.class_id||quizClass)}</select></label><label>Semana<input name="week_start" type="date" required ${locked?'disabled':''} value="${quiz.week_start||quizSelectedWeek}"><span class="field-help">A data será ajustada para a segunda-feira.</span></label><label>Abertura programada<input name="opens_at" type="datetime-local" value="${scheduleInput(quiz.opens_at)}"><span class="field-help">Opcional · horário de São Paulo</span></label><label>Encerramento programado<input name="closes_at" type="datetime-local" value="${scheduleInput(quiz.closes_at)}"><span class="field-help">Opcional · horário de São Paulo</span></label><label class="full">Orientação <span class="field-help">Opcional</span><textarea name="description" maxlength="5000">${esc(quiz.description||'')}</textarea></label><label class="full">Visibilidade<select name="published"><option value="false">${locked?'Encerrado':'Rascunho'}</option><option value="true" ${quiz.published?'selected':''}>Publicado para a turma</option></select></label></div>${locked?'<p class="small muted">Questões publicadas · use Criar cópia para alterar.</p>':''}<div id="quiz-question-editor"></div>${locked?'':'<button type="button" class="btn secondary" id="quiz-add-question">Adicionar questão</button>'}`,async values=>{if(busy)return;const title=values.title.trim();if(!title)throw Error('Informe o título.');const questions=locked?quiz.questions:readQuizEditor();validateQuizQuestions(questions);const fields={title,description:values.description.trim(),published:values.published==='true'};if(!locked){fields.class_id=values.class_id;fields.week_start=quizWeek(values.week_start);fields.questions=questions;if(!state.classes.some(c=>c.id===fields.class_id))throw Error('Selecione uma turma válida.')}const opening=scheduleInstant(values.opens_at),closing=scheduleInstant(values.closes_at);validateQuizSchedule(fields.week_start||quiz.week_start,opening,closing);if(opening||closing||'opens_at'in quiz||'closes_at'in quiz){fields.opens_at=opening;fields.closes_at=closing}busy=true;try{if(local()){const record={...quiz,...fields,id:quiz.id||uid(),row_version:(quiz.row_version||0)+1,created_at:quiz.created_at||new Date().toISOString()};if(record.published&&!record.published_at)record.published_at=new Date().toISOString();await persistLocalQuizzes(quiz.id?quizItems.map(q=>q.id===quiz.id?record:q):[record,...quizItems])}else{const table=client.from('school_quizzes');const r=quiz.id?await table.update({...fields,row_version:quiz.row_version+1}).eq('id',quiz.id).eq('workspace_owner_id',workspaceId).eq('row_version',quiz.row_version).select('id').maybeSingle():await table.insert({workspace_owner_id:workspaceId,...fields}).select('id').single();if(r.error){if(['PGRST204','42703'].includes(r.error.code))throw Error('Recurso indisponível. Atualize os dados e tente novamente.');throw r.error}if(!r.data)throw Error('O quiz foi alterado por outra pessoa. Atualize antes de salvar.');await loadQuizzes()}$('#modal').close();d.classList.remove('quiz-dialog');render();toast(fields.published?'Quiz publicado para a turma.':'Quiz salvo.')}finally{busy=false}});paintQuizQuestions(locked);if($('#quiz-add-question'))$('#quiz-add-question').onclick=()=>{quizEditorQuestions=readQuizEditor();if(quizEditorQuestions.length>=50){toast('O limite é de 50 questões por quiz.');return}quizEditorQuestions.push(blankQuizQuestion());paintQuizQuestions()};d.addEventListener('close',()=>d.classList.remove('quiz-dialog'),{once:true})}
function quizResultHTML(detail,practice=false){const result=detail.result;return `<div class="quiz-result-banner"><span>${icon('trophy')}</span><div><strong>${result.correct_count} de ${result.question_count} acertos</strong><p>${practice?'Treino concluído · ranking inalterado.':'Tentativa registrada.'}</p></div></div>${detail.questions.map((q,i)=>{const chosen=result.answers?.[q.id],correct=chosen===q.correct_option_id;return `<article class="quiz-feedback"><span class="pill">Questão ${i+1} · ${correct?'Acertou':'Não acertou'}</span><h3>${esc(q.prompt)}</h3><p>Sua resposta: ${esc(q.options.find(o=>o.id===chosen)?.text||'—')}</p>${correct?'':`<p><strong>Resposta correta:</strong> ${esc(q.options.find(o=>o.id===q.correct_option_id)?.text||'—')}</p>`}${q.explanation?`<div class="note">${esc(q.explanation)}</div>`:''}</article>`}).join('')}`}
function showQuizDetail(detail,preview=false){const d=$('#modal');d.classList.add('quiz-dialog');d.addEventListener('close',()=>d.classList.remove('quiz-dialog'),{once:true});if(detail.result){d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${esc(detail.title)}</h2>${quizResultHTML(detail)}<div class="form-actions">${appRole==='student'&&!studentPreview?'<button class="btn secondary" id="quiz-practice-result">Refazer para estudar</button>':''}<button class="btn" id="quiz-close">Fechar resultado</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#quiz-close').onclick=()=>d.close();if($('#quiz-practice-result'))$('#quiz-practice-result').onclick=()=>showQuizPractice(detail);d.showModal();return}d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${esc(detail.title)}</h2><p>${esc(detail.description||'Leia cada pergunta e marque uma alternativa.')}</p><div class="note">${preview?'Prévia':detail.can_submit?'Respostas definitivas ao finalizar.':'Quiz encerrado.'}</div><form id="quiz-answer-form">${detail.questions.map((q,i)=>`<fieldset class="quiz-answer-question"><legend><span>${i+1}</span>${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<label class="quiz-answer-option"><input type="radio" name="q:${esc(q.id)}" value="${esc(o.id)}" ${detail.can_submit&&!preview?'required':''} ${!detail.can_submit&&!preview?'disabled':''}><span>${String.fromCharCode(65+j)}</span><div>${esc(o.text)}</div></label>`).join('')}${preview&&q.correct_option_id?`<div class="note quiz-preview-key"><strong>Gabarito:</strong> ${esc(q.options.find(o=>o.id===q.correct_option_id)?.text||'—')}${q.explanation?`<p>${esc(q.explanation)}</p>`:''}</div>`:''}</fieldset>`).join('')}<p id="quiz-submit-error" class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn secondary" id="quiz-cancel">Fechar</button>${detail.can_submit&&!preview?'<button type="submit" class="btn">Finalizar quiz</button>':''}</div></form>`;d.querySelector('.close').onclick=()=>d.close();$('#quiz-cancel').onclick=()=>d.close();$('#quiz-answer-form').onsubmit=async e=>{e.preventDefault();if(preview||!detail.can_submit||busy)return;const form=e.currentTarget;if(!form.reportValidity())return;const fd=new FormData(form),answers=Object.fromEntries(detail.questions.map(q=>[q.id,fd.get('q:'+q.id)]));if(!confirm('Finalizar o quiz? Suas respostas serão definitivas e esta tentativa contará no ranking.'))return;busy=true;const b=form.querySelector('button[type="submit"]');b.disabled=true;try{const r=await client.rpc('school_submit_quiz',{quiz_id:detail.id,submitted_answers:answers});if(r.error)throw r.error;await loadQuizzes();render();d.close();showQuizDetail(r.data);toast('Quiz finalizado. O ranking da turma foi atualizado.')}catch(e){$('#quiz-submit-error').textContent=friendly(e);b.disabled=false}finally{busy=false}};d.showModal()}
async function openQuiz(id){try{if(studentPreview||local()){const q=quizItems.find(q=>q.id===id);if(q)showQuizDetail({...q,can_submit:false,result:null},true);return}const r=await client.rpc('school_get_quiz',{quiz_id:id});if(r.error)throw r.error;showQuizDetail(r.data,appRole==='coordinator')}catch(e){toast(friendly(e))}}
async function openQuizResults(id){if(appRole!=='coordinator'||studentPreview)return;const quiz=quizItems.find(q=>q.id===id);if(!quiz)return;const owner=workspaceId;try{let attempts=[];if(!local()){for(let offset=0;;offset+=500){const r=await client.from('school_quiz_attempts').select('id,answers').eq('workspace_owner_id',owner).eq('quiz_id',id).order('id').range(offset,offset+499);if(r.error)throw r.error;attempts.push(...r.data);if(r.data.length<500)break}}if(owner!==workspaceId||appRole!=='coordinator'||studentPreview)return;const report=quizQuestionResults(quiz.questions,attempts),d=$('#modal');d.classList.add('quiz-results-dialog');d.addEventListener('close',()=>d.classList.remove('quiz-results-dialog'),{once:true});d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Resultados por questão</h2><p>${esc(quiz.title)} · ${esc(className(quiz.class_id))}<br>${date(quiz.week_start)} a ${date(quizWeekEnd(quiz.week_start))}</p><div class="quiz-results-summary"><div><strong>${report.total}</strong><span>Tentativas finalizadas</span></div><div><strong>${report.questionCount}</strong><span>Questões</span></div><div><strong>${report.rate===null?'—':report.rate+'%'}</strong><span>Acertos da turma</span></div></div>${!report.total?empty('Ainda não há respostas',local()?'As respostas oficiais ficam disponíveis com o Supabase conectado.':'Os resultados aparecerão quando os alunos finalizarem este quiz.','','','chart'):report.questions.map(q=>`<article class="quiz-question-result"><div class="actions"><span class="pill">Questão ${q.index}</span><span class="pill">${q.rate}% de acertos</span></div><h3>${esc(q.prompt)}</h3><p class="small muted">${q.correct} acerto(s) · ${q.incorrect} erro(s) · ${q.total} resposta(s)</p><div class="quiz-answer-distribution">${q.alternatives.map((o,i)=>`<div class="${o.correct?'correct-alternative':''}"><div><strong>${String.fromCharCode(65+i)}. ${esc(o.text)}</strong>${o.correct?'<span class="pill">Correta</span>':''}<span>${o.count} resposta(s) · ${Math.round(o.count/q.total*100)}%</span></div><progress value="${o.count}" max="${q.total}" aria-label="Alternativa ${String.fromCharCode(65+i)}: ${o.count} de ${q.total} respostas"></progress></div>`).join('')}</div>${q.explanation?`<div class="note"><strong>Explicação para revisão</strong><p>${esc(q.explanation)}</p></div>`:''}</article>`).join('')}<div class="form-actions"><button class="btn" id="close-quiz-results">Fechar relatório</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#close-quiz-results').onclick=()=>d.close();d.showModal()}catch(e){toast(friendly(databaseFailure(e,'consultar os resultados do quiz')))}}

async function openQuizPractice(id){if(appRole!=='student'||studentPreview)return;try{const owner=workspaceId,user=session?.user.id,r=await client.rpc('school_get_quiz',{quiz_id:id});if(r.error)throw r.error;if(owner!==workspaceId||user!==session?.user.id||appRole!=='student')return;if(!r.data?.result){toast('Conclua a tentativa oficial antes de treinar.');return}showQuizPractice(r.data)}catch(e){toast(friendly(e))}}
function showQuizPractice(detail,finished=null){if(appRole!=='student'||studentPreview||!detail.result)return;const d=$('#modal');d.classList.add('quiz-dialog');d.addEventListener('close',()=>d.classList.remove('quiz-dialog'),{once:true});if(finished){d.innerHTML=`<button class="close" aria-label="Fechar">×</button><span class="pill">Treino · sem pontos</span><h2 style="margin-top:14px">${esc(detail.title)}</h2>${quizResultHTML(finished,true)}<div class="form-actions"><button class="btn secondary" id="practice-again">Refazer treino</button><button class="btn" id="practice-close">Fechar treino</button></div>`;$('#practice-again').onclick=()=>showQuizPractice(detail)}else{d.innerHTML=`<button class="close" aria-label="Fechar">×</button><span class="pill">Treino · sem pontos</span><h2 style="margin-top:14px">${esc(detail.title)}</h2><form id="practice-quiz-form">${detail.questions.map((q,i)=>`<fieldset class="quiz-answer-question"><legend><span>${i+1}</span>${esc(q.prompt)}</legend>${q.options.map((o,j)=>`<label class="quiz-answer-option"><input type="radio" name="practice:${esc(q.id)}" value="${esc(o.id)}" required><span>${String.fromCharCode(65+j)}</span><div>${esc(o.text)}</div></label>`).join('')}</fieldset>`).join('')}<p id="practice-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn secondary" type="button" id="practice-close">Fechar treino</button><button class="btn" type="submit">Corrigir treino</button></div></form>`;$('#practice-quiz-form').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;try{const data=new FormData(e.currentTarget),answers=Object.fromEntries(detail.questions.map(q=>[q.id,data.get('practice:'+q.id)]));showQuizPractice(detail,practiceQuizResult(detail,answers))}catch(err){$('#practice-error').textContent=friendly(err)}}}d.querySelector('.close').onclick=()=>d.close();$('#practice-close').onclick=()=>d.close();if(!d.open)d.showModal()}

async function handleQuizAction(action){const [verb,id]=action.split(':');if(!verb.startsWith('quiz-'))return false;if(verb==='quiz-open'){await openQuiz(id);return true}if(verb==='quiz-practice'){await openQuizPractice(id);return true}if(verb==='quiz-week-prev'||verb==='quiz-week-next'){const day=new Date(quizSelectedWeek+'T12:00:00Z');day.setUTCDate(day.getUTCDate()+(verb==='quiz-week-prev'?-7:7));const target=day.toISOString().slice(0,10);if((appRole==='student'||studentPreview)&&target>quizWeek())return true;quizSelectedWeek=target;await loadQuizRanking();render();return true}if(appRole!=='coordinator')return true;if(verb==='quiz-results'){await openQuizResults(id);return true}if(verb==='quiz-new'||verb==='quiz-edit'||verb==='quiz-copy'){guardNavigation(()=>editQuiz(id,verb==='quiz-copy'));return true}if(verb==='quiz-toggle'){const q=quizItems.find(q=>q.id===id);if(!q)return true;confirmDialog(q.published?'Encerrar este quiz?':'Reabrir este quiz?',q.published?'Novas respostas serão desativadas. As tentativas e os pontos já obtidos serão preservados.':'O quiz ficará disponível apenas no período programado e na semana definida. A tentativa oficial de quem já finalizou será preservada.',async()=>{try{if(local())await persistLocalQuizzes(quizItems.map(x=>x.id===q.id?{...x,published:!x.published,row_version:x.row_version+1}:x));else{const r=await client.from('school_quizzes').update({published:!q.published,row_version:q.row_version+1}).eq('id',id).eq('workspace_owner_id',workspaceId).eq('row_version',q.row_version).select('id').maybeSingle();if(r.error)throw r.error;if(!r.data)throw Error('O quiz foi alterado. Atualize os dados.');await loadQuizzes()}$('#modal').close();render();toast('Disponibilidade atualizada.')}catch(e){toast(friendly(e))}});return true}if(verb==='quiz-delete'){const q=quizItems.find(q=>q.id===id);if(!q||q.published_at)return true;confirmDialog('Excluir rascunho?','Este rascunho será removido. Quizzes já publicados são preservados.',async()=>{try{if(local())await persistLocalQuizzes(quizItems.filter(x=>x.id!==id));else{const r=await client.from('school_quizzes').delete().eq('id',id).eq('workspace_owner_id',workspaceId);if(r.error)throw r.error;await loadQuizzes()}$('#modal').close();render();toast('Rascunho excluído.')}catch(e){toast(friendly(e))}});return true}if(verb==='quiz-sql'||verb==='quiz-schedule-sql'){try{const r=await fetch(verb==='quiz-schedule-sql'?'./quiz-scheduling.sql':'./quizzes.sql');if(!r.ok)throw Error('Arquivo indisponível.');download(verb==='quiz-schedule-sql'?'trilha-agendamento-quizzes.sql':'trilha-quizzes-e-ranking.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}return true}return true}

let registrationReady=false,registrationEnabled=false,registrationRequests=[],pendingRegistration=null;
const uuidValue=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v)?v:null;
function resetRegistration(){registrationReady=false;registrationEnabled=false;registrationRequests=[];pendingRegistration=null}
function registrationWorkspaceHint(){return uuidValue(new URLSearchParams(location.hash.slice(1)).get('inscricao'))||uuidValue(session?.user.user_metadata?.registration_workspace)}
async function loadRegistration(){registrationRequests=[];registrationReady=false;registrationEnabled=false;if(local())return;const r=await client.rpc('school_registration_queue',{workspace_id:workspaceId});if(r.error){if(schemaMissing(r.error))return;throw r.error}const settings=await client.from('school_registration_settings').select('enabled').eq('workspace_owner_id',workspaceId).maybeSingle();if(settings.error)throw settings.error;registrationReady=true;registrationEnabled=!!settings.data?.enabled;registrationRequests=r.data||[]}
async function requestOwnAccess(){const rawName=session.user.user_metadata?.full_name;const name=typeof rawName==='string'&&rawName.trim()?rawName:session.user.email?.split('@')[0]||'Aluno';const r=await client.rpc('school_submit_registration',{requested_name:name,requested_workspace:registrationWorkspaceHint()});if(r.error){if(schemaMissing(r.error))throw Error('Seu acesso ainda não foi liberado. Peça à coordenação para ativar os cadastros ou vincular sua conta.');throw databaseFailure(r.error,'consultar sua solicitação de cadastro')}pendingRegistration=r.data;appRole='pending';studentPortals=[];workspaceId=r.data.workspace_owner_id;return true}
function renderPending(){const declined=pendingRegistration?.state==='declined',inactive=pendingRegistration?.state==='approved';$('#app').innerHTML=`<main class="lock panel pending-access"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="pending-symbol">${icon(declined?'users':'check')}</div><div class="eyebrow">MEU CADASTRO</div><h1>${inactive?'Seu acesso precisa de revisão':declined?'Converse com a coordenação':'Cadastro recebido.'}</h1><p>${inactive?'Seu vínculo de aluno não está ativo. Converse com a coordenação para conferir o acesso.':declined?'Sua solicitação não foi aprovada. Entre em contato com a coordenação para conferir seus dados.':'Seu e-mail está confirmado. A coordenação vai conferir o cadastro e liberar seu acesso às notas, presença, atividades e financeiro.'}</p><div class="pending-identity"><strong>${esc(pendingRegistration?.full_name||'')}</strong><span>${esc(session.user.email)}</span><span class="pill">${inactive?'Acesso não ativo':declined?'Não aprovado':'Aguardando aprovação'}</span></div><div class="actions">${btn('Verificar liberação','refresh-access','','refresh')}${btn('Sair da conta','logout','secondary','logout')}</div></main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action))}
function signupError(error){if(/Signups not allowed|signup.*disabled|signups.*disabled/i.test(error.message||''))return 'O cadastro ainda está desativado. Avise a coordenação para habilitar novos cadastros no Supabase.';if(/rate.limit|too many|security purposes/i.test(error.message||''))return 'Aguarde alguns minutos antes de tentar novamente.';return friendly(error)}
function renderRegister(){if(!client){toast('A coordenação precisa configurar a conexão da Trilha primeiro.');return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="eyebrow">FAÇA PARTE DA TRILHA</div><h1>Criar minha conta</h1><p>Confirme seu e-mail e aguarde a liberação da coordenação para acessar seus registros.</p><form id="signup-form"><label>Nome completo<input name="full_name" required maxlength="120" autocomplete="name" placeholder="Como você se chama?"></label><label>E-mail<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="Seu e-mail pessoal"></label><label>Senha<input name="password" type="password" required minlength="8" autocomplete="new-password"><span class="field-help">Use pelo menos 8 caracteres.</span></label><label>Confirmar senha<input name="confirmation" type="password" required minlength="8" autocomplete="new-password"></label><p id="signup-error" class="login-error" role="alert"></p><button type="submit" class="btn">Criar conta ${icon('arrow')}</button></form><div class="auth-switch">Já tem uma conta? ${btn('Entrar','auth-login','text')}</div></main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));$('#signup-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('button[type="submit"]');button.disabled=true;$('#signup-error').textContent='';try{const values=new FormData(form),name=values.get('full_name').trim(),email=values.get('email').trim(),password=values.get('password');if(!name)throw Error('Informe seu nome completo.');if(password!==values.get('confirmation'))throw Error('As senhas não conferem.');const target=await client.rpc('school_registration_target',{requested_workspace:registrationWorkspaceHint()});if(target.error){if(schemaMissing(target.error))throw Error('A coordenação precisa ativar a atualização de cadastro no aplicativo.');throw target.error}if(!target.data)throw Error('Peça à coordenação o link de cadastro desta Trilha.');const result=await client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname,data:{full_name:name,registration_workspace:target.data}}});if(result.error)throw result.error;if(result.data.session){session=result.data.session;await load();render();return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="pending-symbol">${icon('check')}</div><h1>Confira seu e-mail.</h1><p>Abra a mensagem de confirmação enviada para <strong>${esc(email)}</strong>. Depois de confirmar, entre na sua conta para enviar o cadastro à coordenação.</p><p class="field-help">Se a mensagem não aparecer, confira a pasta de spam.</p>${btn('Voltar para entrar','auth-login','','arrow')}</main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action))}catch(error){$('#signup-error').textContent=signupError(error);button.disabled=false}}}
function registrationPanel(){const pending=registrationRequests.filter(r=>r.state==='pending');return `<section class="panel"><div class="panel-header"><h2>Solicitações de cadastro</h2><span class="pill">${pending.length} aguardando</span></div><div class="panel-body">${!registrationReady?'<p class="small muted">Cadastros indisponíveis.</p>':!registrationEnabled?`${ownsWorkspace()?btn('Ativar cadastro','registration-enable','','check'):'<p class="field-help">O responsável principal pode ativar os cadastros.</p>'}`:`${pending.length?pending.map(r=>`<article class="registration-request"><div><strong>${esc(r.full_name)}</strong><span>${esc(r.email)}</span><small>Solicitado em ${new Date(r.created_at).toLocaleDateString('pt-BR')}</small></div><div class="actions">${btn('Aprovar acesso','registration-approve:'+r.id,'secondary','check')}${btn('Recusar','registration-decline:'+r.id,'text')}</div></article>`).join(''):empty('Nenhum cadastro aguardando','As novas solicitações aparecerão aqui depois da confirmação do e-mail e do primeiro login.','','','users')}<div class="actions">${btn('Copiar link de cadastro','registration-link','secondary','arrow')}${btn('Atualizar solicitações','refresh-access','text','refresh')}</div>`}</div></section>`}
function reviewRegistration(id){const r=registrationRequests.find(r=>r.id===id&&r.state==='pending');if(!r)return;modal('Aprovar acesso','Confira o e-mail e escolha o cadastro que pertence a esta pessoa.',`<div class="pending-identity"><strong>${esc(r.full_name)}</strong><span>${esc(r.email)}</span></div><label>Cadastro do aluno<select name="student_id" required>${options(state.students,'','Selecione o aluno correto')}</select></label>${btn('Cadastrar um novo aluno','registration-new-student:'+id,'secondary','plus')}`,async values=>{const result=await client.rpc('school_review_registration',{request_id:id,accept_request:true,student_record_id:values.student_id});if(result.error)throw result.error;await loadAdminLearning();await loadRegistration();$('#modal').close();render();toast('Acesso do aluno aprovado.')})}
async function copyRegistrationLink(){const link=new URL(location.origin+location.pathname);if(!deploymentConfig)link.hash='acesso='+encodeURIComponent(JSON.stringify({url:config.url,key:config.key}));const hash=new URLSearchParams(link.hash.slice(1));hash.set('inscricao',workspaceId);link.hash=hash.toString();try{await navigator.clipboard.writeText(link.href);toast('Link de cadastro copiado.')}catch{const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Link de cadastro</h2><p>Compartilhe com as pessoas que vão se cadastrar.</p><textarea id="registration-link" readonly>${esc(link.href)}</textarea>`;d.querySelector('.close').onclick=()=>d.close();d.showModal();$('#registration-link').select()}}
async function handleRegistrationAction(action){const [verb,id]=action.split(':');if(verb==='auth-register'){renderRegister();return true}if(verb==='auth-login'){renderLogin();return true}if(!verb.startsWith('registration-'))return false;if(appRole==='student'||appRole==='pending'||local())return true;if(verb==='registration-sql'){try{const r=await fetch('./self-registration.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-cadastro-autonomo.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}}else if(verb==='registration-enable'){try{const r=await client.rpc('school_enable_registration',{workspace_id:workspaceId});if(r.error)throw r.error;await loadRegistration();render();toast('Recebimento de cadastros ativado.')}catch(e){toast(friendly(e))}}else if(verb==='registration-approve')reviewRegistration(id);else if(verb==='registration-decline'){confirmDialog('Recusar esta solicitação?','A pessoa não terá acesso aos registros e poderá conversar com a coordenação para conferir os dados.',async()=>{const r=await client.rpc('school_review_registration',{request_id:id,accept_request:false,student_record_id:null});if(r.error){toast(friendly(r.error));return}await loadRegistration();$('#modal').close();render();toast('Solicitação analisada.')})}else if(verb==='registration-link')await copyRegistrationLink();else if(verb==='registration-new-student'){if(!state.classes.length){toast('Crie uma turma em Turmas antes de cadastrar o aluno.');return true}const r=registrationRequests.find(r=>r.id===id);$('#modal').close();editor('student');const input=$('#modal-form [name="name"]');if(input&&r)input.value=r.full_name}return true}

let appRole='coordinator', studentPreview=false, previewStudentId='', learnerPage='home', learnerLearningTab='materials', materialSearch='', studentPortals=[], portalIndex=0, learningItems=[], studentLinks=[], portalReady=false;
const LEARNING_KEY='trilha-learning-v1';let learningSnapshot=null;
function resetStudentArea(){resetRecordedLessons();appRole='coordinator';studentPreview=false;previewStudentId='';learnerPage='home';learnerLearningTab='materials';materialSearch='';studentPortals=[];portalIndex=0;learningItems=[];studentLinks=[];portalReady=false}
function resourceURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
async function loadStudentIdentity(){const r=await client.rpc('school_student_portals');if(r.error){if(schemaMissing(r.error))throw Error('Seu acesso ainda não foi liberado. Peça à coordenação para vincular sua conta ao cadastro de aluno.');throw databaseFailure(r.error,'consultar sua matrícula')}studentPortals=r.data||[];if(!studentPortals.length){await requestOwnAccess();return}appRole='student';portalReady=true;portalIndex=Math.min(portalIndex,studentPortals.length-1);workspaceId=studentPortals[portalIndex].owner_id}
async function loadAdminLearning(){
 if(appRole==='student')return;
 if(local()){const raw=localStorage.getItem(LEARNING_KEY);learningSnapshot=raw;try{learningItems=JSON.parse(raw||'[]')}catch{learningItems=[]}studentLinks=[];portalReady=false;return}
 const r=await client.from('school_learning_items').select('*').eq('workspace_owner_id',workspaceId).order('created_at',{ascending:false});if(r.error){if(schemaMissing(r.error)){portalReady=false;learningItems=[];studentLinks=[];return}throw r.error}learningItems=r.data||[];
 const links=await client.rpc('school_student_links',{workspace_id:workspaceId});if(links.error)throw links.error;studentLinks=links.data||[];portalReady=true;
}
function previewPortal(){const s=state.students.find(s=>s.id===previewStudentId);if(!s)return null;const grades=state.grades.filter(g=>g.studentId===s.id);return {owner_id:workspaceId,student:{id:s.id,name:s.name,classId:s.classId},class_name:className(s.classId),grades,assessments:state.assessments.filter(a=>a.classId===s.classId||grades.some(g=>g.assessmentId===a.id)),attendance:state.attendance.filter(a=>a.studentId===s.id),notices:state.notices,learning_items:learningItems.filter(i=>i.class_id===s.classId&&i.published),submissions:[]}}
const currentPortal=()=>studentPreview?previewPortal():studentPortals[portalIndex];
const portalAverage=p=>p.grades.length?p.grades.reduce((sum,g)=>sum+Number(g.value),0)/p.grades.length:null;
const portalFrequency=p=>{const calls=p.attendance.filter(a=>a.status!=='excused');return calls.length?calls.filter(a=>a.status==='present').length/calls.length*100:null};
function learnerNotice(n){return `<article class="notice"><span class="pill">${n.category==='important'?'Importante':'Comunicado'}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${date(n.date)} · Coordenação</small></article>`}
function learningCard(i,p){const done=p.submissions.find(s=>s.item_id===i.id&&s.completed);return `<article class="learning-card"><div class="learning-card-top"><span class="learning-type">${icon(i.kind==='activity'?'check':'book')}${i.kind==='activity'?'Atividade opcional':'Material de apoio'}</span>${done?'<span class="pill completed-pill">Concluída</span>':''}</div><h3>${esc(i.title)}</h3><p>${esc(i.body.slice(0,180))}${i.body.length>180?'…':''}</p><div class="learning-card-footer"><span class="small muted">${i.due_date?'Sugestão: '+date(i.due_date):i.kind==='activity'?'No seu ritmo · sem nota':'Para continuar aprendendo'}</span>${btn(i.kind==='activity'?(done?'Ver resposta':'Fazer atividade'):'Abrir material','learner-item:'+i.id,'text','arrow')}</div></article>`}
function coordinatorOverview(){const pending=registrationRequests.filter(r=>r.state==='pending'),overdue=financeSummary(financeCharges).overdue,alerts=attendanceAlerts(state.students,state.attendance);return `<section class="panel dashboard-overview"><div class="panel-header"><h2>O que precisa da sua atenção</h2></div><div class="dashboard-actions"><article><span class="dashboard-action-icon">${icon('users')}</span><h3>Cadastros para aprovar</h3><strong>${registrationReady?pending.length:'—'}</strong><p>${registrationReady?pending.length?'Pessoas aguardando a conferência do acesso.':'Nenhuma solicitação pendente.':local()?'Disponível com o Supabase conectado.':'Cadastros ainda não disponíveis.'}</p>${btn('Conferir cadastros','go-student-area','secondary','arrow')}</article><article><span class="dashboard-action-icon">${icon('wallet')}</span><h3>Pagamentos vencidos</h3><strong>${local()||financeReady?overdue.length:'—'}</strong><p>${local()||financeReady?overdue.length?formatMoney(overdue.reduce((sum,c)=>sum+c.amount_cents,0))+' em cobranças vencidas.':'Nenhuma cobrança vencida nos registros.':'Financeiro ainda não disponível.'}</p>${btn('Conferir financeiro','overview-finance','secondary','arrow')}</article><article><span class="dashboard-action-icon">${icon('check')}</span><h3>Atenção à presença</h3><strong>${alerts.length}</strong><p>Alunos com 2 ou mais faltas nas últimas 4 chamadas registradas da turma atual.</p>${btn('Ver acompanhamento','go-reports','secondary','arrow')}</article></div>${alerts.length?`<div class="dashboard-attendance"><h3>Alunos para acompanhar</h3>${alerts.slice(0,5).map(s=>`<div><strong>${esc(s.name)}</strong><span>${esc(className(s.classId))} · ${s.absences} faltas em ${s.recorded} chamadas</span></div>`).join('')}${alerts.length>5?`<p class="small muted">Mais ${alerts.length-5} alunos no acompanhamento.</p>`:''}</div>`:''}</section>`}
function learnerPriorities(p){const available=local()||financeReady,summary=financeSummary(financeCharges.filter(c=>c.student_id===p.student.id)),quizzes=quizStudentItems(p).filter(q=>q.week_start===quizWeek()&&(q.can_submit||studentPreview)),notices=prioritizeNotices(p.notices),important=notices.filter(n=>n.category==='important');return `<section class="panel dashboard-overview"><div class="panel-header"><h2>Seus próximos passos</h2></div><div class="dashboard-actions"><article><span class="dashboard-action-icon">${icon('wallet')}</span><h3>Próximo vencimento</h3><strong class="dashboard-date">${available&&summary.next?date(summary.next.due_date):'—'}</strong><p>${!available?'Consulte a coordenação para confirmar os pagamentos.':summary.next?formatMoney(summary.next.amount_cents)+' · '+esc(summary.next.description):'Nenhum próximo vencimento cadastrado.'}</p>${available&&summary.overdue.length?`<p class="dashboard-warning">${summary.overdue.length} cobrança(s) em atraso. Confira seu financeiro.</p>`:''}${btn('Meus pagamentos','learner-tab:finance','secondary','arrow')}</article><article><span class="dashboard-action-icon">${icon('trophy')}</span><h3>Quiz da semana</h3><strong>${quizReady||local()?quizzes.length:'—'}</strong><p>${!quizReady&&!local()?'Os quizzes estão sendo preparados pela coordenação.':quizzes.length?'Quiz disponível para praticar. Participação opcional, sem alterar suas notas.':'Nenhum quiz aguardando resposta nesta semana.'}</p>${btn(quizzes.length?'Ver quiz da semana':'Quiz e ranking','learner-tab:quizzes','secondary','arrow')}</article><article><span class="dashboard-action-icon">${icon('bell')}</span><h3>Avisos importantes</h3><strong>${important.length}</strong><p>${important.length?esc(important[0].title):'Nenhum comunicado marcado como importante.'}</p>${btn('Ler os avisos','learner-tab:notices','secondary','arrow')}</article></div></section>`}

function learnerHome(p){const average=portalAverage(p),frequency=portalFrequency(p),materials=p.learning_items.filter(i=>i.kind==='material'),weeklyQuizzes=quizStudentItems(p).filter(q=>q.week_start===quizWeek()),done=weeklyQuizzes.filter(q=>q.result).length;return heading('Olá, '+esc(p.student.name.split(' ')[0])+'.','Seu espaço para aprender, acompanhar e continuar crescendo.',btn('Continuar aprendendo','learner-tab:learning','','arrow'))+`<div class="learner-class-line"><span class="pill">${esc(p.class_name)}</span><span>Minha Trilha</span></div><section class="stats">${stat('Minha média',average===null?'—':num(average),'Somente avaliações com nota','grades')}${stat('Minha frequência',frequency===null?'—':num(frequency)+'%','Justificativas fora do cálculo','check')}${stat('Quizzes finalizados',quizReady||local()?done+'/'+weeklyQuizzes.length:'—','Nesta semana · não alteram a média','trophy')}${stat('Avisos',p.notices.length,'Comunicados da coordenação','bell')}</section>${learnerPriorities(p)}<div class="learner-home-grid"><section class="panel"><div class="panel-header"><h2>Para esta semana</h2>${btn('Ver tudo','learner-tab:learning','text','arrow')}</div><div class="learning-stack">${materials.length?materials.slice(0,2).map(i=>learningCard(i,p)).join(''):empty('Seu próximo passo aparece aqui','Quando a coordenação publicar materiais de apoio para sua turma, você poderá acessá-los neste espaço.','','','book')}</div></section><section class="panel"><div class="panel-header"><h2>Fique por dentro</h2>${btn('Todos os avisos','learner-tab:notices','text','arrow')}</div>${p.notices.length?prioritizeNotices(p.notices).slice(0,3).map(learnerNotice).join(''):empty('Tudo em dia','Os novos comunicados da coordenação aparecerão aqui.','','','bell')}</section></div>`}
function learnerGrades(p){const average=portalAverage(p);return heading('Minhas notas','Acompanhe suas avaliações e os comentários da coordenação.')+`<div class="learner-score"><div><span class="eyebrow">MÉDIA SIMPLES</span><strong>${average===null?'—':num(average)}<small>/ 10</small></strong></div><p>As atividades semanais são opcionais e não entram na sua média.</p></div><section class="panel"><div class="panel-header"><h2>Avaliações</h2><span class="pill">${p.grades.length} notas lançadas</span></div>${p.assessments.length?`<div class="table-wrap"><table><thead><tr><th>Avaliação</th><th>Data</th><th>Nota</th><th>Comentário</th></tr></thead><tbody>${[...p.assessments].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const g=p.grades.find(g=>g.assessmentId===a.id);return `<tr><td><strong>${esc(a.title)}</strong></td><td>${date(a.date)}</td><td><span class="learner-grade">${g?num(g.value):'—'}</span>${g?'':'<span class="small muted"> Aguardando</span>'}</td><td>${esc(g?.note||'—')}</td></tr>`}).join('')}</tbody></table></div>`:empty('Ainda não há avaliações','As avaliações e suas notas aparecerão aqui quando forem cadastradas.','','','grades')}</section>`}
function learnerAttendance(p){const f=portalFrequency(p);return heading('Minha presença','Consulte o histórico das aulas e sua participação.')+`<section class="stats">${stat('Frequência',f===null?'—':num(f)+'%','Presenças ÷ chamadas sem justificativa','check')}${stat('Presenças',p.attendance.filter(a=>a.status==='present').length,'Aulas em que você esteve presente','users')}${stat('Faltas',p.attendance.filter(a=>a.status==='absent').length,'Ausências registradas','book')}${stat('Justificadas',p.attendance.filter(a=>a.status==='excused').length,'Fora do cálculo de frequência','grades')}</section><section class="panel"><div class="panel-header"><h2>Histórico de chamadas</h2></div>${p.attendance.length?`<div class="table-wrap"><table><thead><tr><th>Data da aula</th><th>Situação</th></tr></thead><tbody>${[...p.attendance].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${date(a.date)}</td><td><span class="pill attendance-${a.status}">${{present:'Presente',absent:'Falta',excused:'Justificada'}[a.status]}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Sua primeira chamada aparece aqui','Os registros são feitos pela coordenação.','','','check')}</section>`}
let recordedLessons=[],lessonNotes=[],lessonsReady=false,lessonsError='',lessonEditor=null;
function resetRecordedLessons(){if(lessonEditor){clearTimeout(lessonEditor.timer);$('#modal')?.close();if($('#modal'))$('#modal').innerHTML=''}recordedLessons=[];lessonNotes=[];lessonsReady=false;lessonsError='';lessonEditor=null}
async function lessonRows(table,fields){const items=[];for(let offset=0;;offset+=500){const r=await client.from(table).select(fields).eq('workspace_owner_id',workspaceId).order(table==='school_lesson_notes'?'lesson_id':'id').range(offset,offset+499);if(r.error)throw r.error;items.push(...r.data);if(r.data.length<500)return items}}
async function loadRecordedLessons(){recordedLessons=[];lessonNotes=[];lessonsReady=false;lessonsError='';if(local()){try{recordedLessons=JSON.parse(localStorage.getItem('trilha-recorded-lessons-v1')||'[]')}catch{}return}if(!workspaceId||appRole==='pending')return;try{recordedLessons=await lessonRows('school_recorded_lessons','*');if(appRole==='student')lessonNotes=await lessonRows('school_lesson_notes','lesson_id,notes,completed,revision');lessonsReady=true}catch(e){recordedLessons=[];lessonNotes=[];lessonsError=schemaMissing(e)?'':friendly(databaseFailure(e,'consultar as aulas gravadas'))}}
function lessonsForStudent(p){return recordedLessons.filter(l=>l.published&&l.class_id===p.student.classId).sort((a,b)=>b.lesson_date.localeCompare(a.lesson_date))}
function learnerRecordedLessons(p){const items=lessonsForStudent(p);return heading('Aulas gravadas','Assista às aulas da sua turma e registre suas próprias anotações.')+(!local()&&!lessonsReady?`<section class="panel">${empty('As aulas chegam por aqui',lessonsError||'A coordenação está preparando as aulas gravadas.','','','book')}</section>`:`<div class="learning-grid">${items.length?items.map(l=>`<article class="learning-card"><div class="learning-card-top"><span class="pill">${date(l.lesson_date)}</span>${!studentPreview&&lessonNotes.some(n=>n.lesson_id===l.id&&n.completed)?'<span class="pill">Assistida</span>':''}</div><h3>${esc(l.title)}</h3><p>${esc(l.description.slice(0,180))}</p><div class="learning-card-footer"><span class="small muted">Aula da sua turma</span>${btn('Assistir aula','lesson-watch:'+l.id,'','arrow')}</div></article>`).join(''):`<section class="panel">${empty('Em breve, novas aulas','As gravações publicadas para sua turma aparecerão aqui.','','','book')}</section>`}</div>`)}
function recordedLessonsAdmin(){return `<section class="panel recorded-admin"><div class="panel-header"><h2>Aulas gravadas</h2>${btn('Nova aula gravada','lesson-new','secondary','plus')}</div><div class="panel-body">${recordedLessons.length?recordedLessons.slice().sort((a,b)=>b.lesson_date.localeCompare(a.lesson_date)).map(l=>`<article class="admin-learning-item"><div><span class="pill">${l.published?'Publicado':l.published_at?'Arquivado':'Rascunho'}</span><h3>${esc(l.title)}</h3><p class="small muted">${esc(className(l.class_id))} · ${date(l.lesson_date)}</p></div><div class="actions">${btn('Prévia da aula','lesson-watch:'+l.id,'secondary','book')}${iconBtn('Editar aula gravada','lesson-edit:'+l.id,'edit')}</div></article>`).join(''):empty('Sua primeira aula gravada','Envie o vídeo ao YouTube como não listado e cadastre o link aqui.','lesson-new','Cadastrar aula','book')}</div></section>`}
function editRecordedLesson(id){if(!local()&&!lessonsReady){toast('Recurso indisponível. Atualize os dados e tente novamente.');return}if(!state.classes.length){toast('Cadastre uma turma primeiro.');return}const lesson=recordedLessons.find(l=>l.id===id)||{},locked=!!lesson.published_at;modal(lesson.id?'Editar aula gravada':'Nova aula gravada','Envie o vídeo ao YouTube como não listado e cole o link. A incorporação precisa estar permitida no YouTube.',`<div class="form-grid"><label class="full">Título da aula<input name="title" required maxlength="120" value="${esc(lesson.title||'')}"></label><label>Turma<select name="class_id" required ${locked?'disabled':''}>${options(state.classes,lesson.class_id)}</select></label><label>Data da aula<input name="lesson_date" type="date" required value="${lesson.lesson_date||financeToday()}"></label><label class="full">Link do YouTube<input name="youtube_url" type="url" required ${locked?'disabled':''} value="${lesson.youtube_id?'https://www.youtube.com/watch?v='+lesson.youtube_id:''}" placeholder="https://www.youtube.com/watch?v=…"></label><label class="full">Descrição<textarea name="description" maxlength="10000">${esc(lesson.description||'')}</textarea></label><label class="full">Material de apoio <span class="field-help">Link HTTPS opcional</span><input name="resource_url" type="url" value="${esc(lesson.resource_url||'')}" maxlength="2000"></label><label class="full">Visibilidade<select name="published"><option value="false">${locked?'Arquivado':'Rascunho'}</option><option value="true" ${lesson.published?'selected':''}>Publicado para a turma</option></select></label></div>${locked?'<p class="small muted">Vídeo e turma bloqueados após a publicação.</p>':''}`,async values=>{const video=locked?lesson.youtube_id:youtubeId(values.youtube_url);if(!video)throw Error('Informe um link HTTPS válido de vídeo do YouTube.');const link=values.resource_url.trim();if(link&&!resourceURL(link))throw Error('Informe um link HTTPS válido para o material.');const fields={title:values.title.trim(),description:values.description.trim(),lesson_date:values.lesson_date,resource_url:link?resourceURL(link):'',published:values.published==='true',class_id:locked?lesson.class_id:values.class_id,youtube_id:video};if(!fields.title||!state.classes.some(c=>c.id===fields.class_id))throw Error('Informe o título e a turma.');if(local()){const record={...lesson,...fields,id:lesson.id||uid(),row_version:(lesson.row_version||0)+1,published_at:lesson.published_at||(fields.published?new Date().toISOString():null)};recordedLessons=lesson.id?recordedLessons.map(l=>l.id===lesson.id?record:l):[record,...recordedLessons];localStorage.setItem('trilha-recorded-lessons-v1',JSON.stringify(recordedLessons))}else{const r=lesson.id?await client.from('school_recorded_lessons').update({...fields,row_version:lesson.row_version+1}).eq('id',lesson.id).eq('workspace_owner_id',workspaceId).eq('row_version',lesson.row_version).select('id').maybeSingle():await client.from('school_recorded_lessons').insert({workspace_owner_id:workspaceId,...fields}).select('id').single();if(r.error)throw r.error;if(!r.data)throw Error('A aula foi alterada em outra janela. Atualize antes de salvar.');await loadRecordedLessons()}$('#modal').close();render();toast('Aula gravada salva.')})}
function lessonNoteStatus(message){if($('#lesson-note-status'))$('#lesson-note-status').textContent=message}
async function saveLessonNote(editor=lessonEditor){if(!editor||editor.preview||editor.saving)return editor?.saving;clearTimeout(editor.timer);if(!editor.dirty)return true;const text=editor.text,completed=editor.completed,version=editor.version,userId=session?.user.id;editor.saving=(async()=>{lessonNoteStatus('Salvando…');try{const r=await client.rpc('school_save_lesson_note',{lesson_id:editor.id,expected_revision:editor.revision,note_text:text,is_completed:completed});if(r.error)throw r.error;if(lessonEditor!==editor||session?.user.id!==userId)return false;editor.revision=r.data.revision;lessonNotes=lessonNotes.filter(n=>n.lesson_id!==editor.id).concat(r.data);editor.dirty=editor.version!==version;lessonNoteStatus(editor.dirty?'Há novas alterações para salvar…':'Anotações salvas.');editor.error='';return true}catch(e){editor.error=friendly(e);lessonNoteStatus('Não foi possível salvar: '+editor.error+' Mantenha a aula aberta e tente novamente ou baixe uma cópia.');return false}finally{editor.saving=null;if(editor.dirty&&!editor.error&&lessonEditor===editor)editor.timer=setTimeout(()=>saveLessonNote(editor),500)}})();return editor.saving}
async function closeRecordedLesson(){const editor=lessonEditor;if(editor&&!editor.preview){if(editor.saving)await editor.saving;if(editor.dirty){const ok=await saveLessonNote(editor);if(!ok||editor.dirty)return}}if(editor)clearTimeout(editor.timer);lessonEditor=null;$('#modal').close();render()}
async function openRecordedLesson(id){const lesson=recordedLessons.find(l=>l.id===id);if(!lesson)return;const preview=appRole==='coordinator'||studentPreview||local();if(!preview&&!lessonsForStudent(currentPortal()).some(l=>l.id===id))return;const existing=preview?null:lessonNotes.find(n=>n.lesson_id===id),d=$('#modal');const editor={id,preview,revision:existing?.revision||0,text:existing?.notes||'',completed:!!existing?.completed,version:0,dirty:false,saving:null,error:''};lessonEditor=editor;d.classList.add('lesson-player-dialog');d.addEventListener('close',()=>{clearTimeout(editor.timer);d.classList.remove('lesson-player-dialog');if(lessonEditor===editor)lessonEditor=null},{once:true});d.innerHTML=`<button class="close" aria-label="Fechar">×</button><span class="pill">${date(lesson.lesson_date)}</span><h2 style="margin-top:12px">${esc(lesson.title)}</h2><div class="lesson-video"><iframe src="${youtubeEmbed(lesson.youtube_id)}" title="${esc(lesson.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="lesson-description">${esc(lesson.description)}</p><p class="small muted">Se o vídeo estiver indisponível, confira a permissão de incorporação com a coordenação.</p><div class="actions"><a class="btn secondary" href="https://www.youtube.com/watch?v=${lesson.youtube_id}" target="_blank" rel="noopener noreferrer">Abrir no YouTube</a>${resourceURL(lesson.resource_url)?`<a class="btn secondary" href="${esc(resourceURL(lesson.resource_url))}" target="_blank" rel="noopener noreferrer">Material de apoio</a>`:''}</div><section class="lesson-note-area"><h3>Minhas anotações</h3><p class="small muted">${preview?'Prévia da coordenação: as anotações pessoais ficam disponíveis somente na conta do aluno.':'Anotações privadas · salvamento automático.'}</p><textarea id="lesson-note-text" maxlength="30000" rows="8" aria-label="Minhas anotações" placeholder="O que você aprendeu nesta aula?" ${preview?'disabled':''}>${esc(editor.text)}</textarea><label class="completion-label"><input type="checkbox" id="lesson-completed" ${editor.completed?'checked':''} ${preview?'disabled':''}>Marcar aula como assistida</label><p id="lesson-note-status" role="status" aria-live="polite">${preview?'Envios desativados na prévia.':existing?'Anotações salvas.':'Suas anotações aparecerão aqui.'}</p>${preview?'':`<div class="actions"><button class="btn secondary" id="lesson-save">Salvar agora</button><button class="btn text" id="lesson-copy">Baixar minhas anotações</button><button class="btn text" id="lesson-discard">Fechar sem salvar</button></div>`}</section><div class="form-actions"><button class="btn" id="lesson-close">Fechar aula</button></div>`;d.querySelector('.close').onclick=closeRecordedLesson;$('#lesson-close').onclick=closeRecordedLesson;d.oncancel=e=>{e.preventDefault();closeRecordedLesson()};d.addEventListener('close',()=>{d.oncancel=null},{once:true});if(!preview){const changed=()=>{editor.text=$('#lesson-note-text').value;editor.completed=$('#lesson-completed').checked;editor.version++;editor.dirty=true;editor.error='';lessonNoteStatus('Alterações ainda não salvas…');clearTimeout(editor.timer);editor.timer=setTimeout(()=>saveLessonNote(editor),800)};$('#lesson-note-text').oninput=changed;$('#lesson-completed').onchange=changed;$('#lesson-save').onclick=()=>saveLessonNote(editor);$('#lesson-copy').onclick=()=>download('minhas-anotacoes.txt',editor.text,'text/plain');$('#lesson-discard').onclick=async()=>{if(editor.saving)await editor.saving;if(editor.dirty&&!confirm('Descartar as alterações que ainda não foram salvas? Baixe uma cópia antes de continuar, se precisar.'))return;editor.dirty=false;clearTimeout(editor.timer);lessonEditor=null;d.close();render()}}d.showModal()}
async function handleLessonAction(action){const [verb,id]=action.split(':');if(!verb.startsWith('lesson-'))return false;if(verb==='lesson-watch'){await openRecordedLesson(id);return true}if(appRole!=='coordinator'||studentPreview)return true;if(verb==='lesson-new'||verb==='lesson-edit'){guardNavigation(()=>editRecordedLesson(id));return true}if(verb==='lesson-sql'){try{const r=await fetch('./recorded-lessons.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-aulas-gravadas.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}}return true}
window.addEventListener('beforeunload',e=>{if(lessonEditor?.dirty){e.preventDefault();e.returnValue=''}});

function learnerLearning(p){const materials=p.learning_items.filter(i=>i.kind==='material');const tabs=`<nav class="learning-sections" aria-label="Seções de Aprender">${[['materials','Livros e materiais','book'],['lessons','Aulas gravadas','book'],['quizzes','Quiz e ranking','trophy']].map(([id,label,i])=>`<button class="btn ${learnerLearningTab===id?'':'secondary'}" data-action="learner-learning:${id}" ${learnerLearningTab===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav>`;if(learnerLearningTab==='quizzes')return tabs+learnerQuizPage(p);if(learnerLearningTab==='lessons')return tabs+learnerRecordedLessons(p);return heading('Aprender durante a semana','Livros, materiais didáticos e quizzes para continuar sua formação.')+tabs+`<label class="material-search-label">Buscar livros e materiais<input id="material-search" type="search" value="${esc(materialSearch)}" placeholder="Buscar por título ou assunto…" autocomplete="off"><span class="field-help">Busca no título e na descrição dos materiais da sua turma.</span></label><div id="material-results" aria-live="polite">${materialSearchResults(p)}</div>`}
function materialSearchResults(p){const items=searchMaterials(p.learning_items,materialSearch);return `<p class="small muted">${items.length} material(is) encontrado(s)</p>`+(items.length?`<div class="learning-grid">${items.map(i=>learningCard(i,p)).join('')}</div>`:`<section class="panel">${empty(materialSearch?'Nenhum material encontrado':'Em breve, livros e materiais',materialSearch?'Tente outro título ou assunto.':'Os livros e materiais didáticos publicados para sua turma aparecerão aqui.','','','book')}</section>`)}
function bindMaterialSearch(){const input=$('#material-search');if(!input)return;input.oninput=()=>{materialSearch=input.value;const results=$('#material-results');results.innerHTML=materialSearchResults(currentPortal());results.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action))}}
function navigateLearner(target,section){if(target==='quizzes'){learnerPage='learning';learnerLearningTab='quizzes'}else{learnerPage=target;if(target==='learning')learnerLearningTab=section||'materials'}if(learnerPage==='learning'&&learnerLearningTab==='quizzes')loadQuizRanking().then(renderStudent);else renderStudent();window.scrollTo(0,0)}
function learnerProfile(p){avatarDraft=myProfile.avatar_data||'';return heading('Meu perfil','Seus dados pessoais na Trilha Apostólica.')+`<section class="panel learner-profile-panel"><div class="panel-header"><h2>Minha conta</h2><span class="pill">Aluno</span></div><div class="panel-body"><form id="profile-form"><fieldset ${studentPreview?'disabled':''}><div class="profile-photo-row"><div id="photo-preview">${personAvatar(studentPreview?{}:myProfile,studentPreview?p.student.name:myName(),true)}</div><div><label class="btn secondary photo-label">Escolher foto<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button class="btn text" type="button" id="remove-photo">Remover foto</button><p class="field-help">JPG, PNG ou WebP · até 5 MB</p></div></div><div class="form-grid"><label class="full">Nome completo<input name="display_name" required maxlength="120" value="${esc(studentPreview?p.student.name:myProfile.display_name||p.student.name)}"></label><label class="full">E-mail da conta<input type="email" readonly value="${esc(studentPreview?'':session.user.email)}"></label><label>Telefone<input name="phone" type="tel" maxlength="30" autocomplete="tel" value="${esc(studentPreview?'':myProfile.phone)}"></label><input name="responsibility" type="hidden" value="${esc(myProfile.responsibility)}"></div><p id="profile-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">Salvar perfil</button></div></fieldset></form><div class="note">Turma: <strong>${esc(p.class_name)}</strong>. Alterações na matrícula são feitas pela coordenação.</div></div></section>`}
function renderStudent(){const p=currentPortal();if(!p){if(studentPreview){studentPreview=false;render();return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><h1>Acesso indisponível</h1><p>Seu cadastro não está vinculado a uma turma com acesso ativo. Converse com a coordenação.</p><div class="actions">${btn('Atualizar acesso','refresh-access','secondary','refresh')}${btn('Sair da conta','logout','','logout')}</div></main>`;bind();return}const nav=[['home','Início','home'],['learning','Aprender','book'],['grades','Notas','grades'],['attendance','Presença','check'],['finance','Financeiro','wallet'],['notices','Avisos','bell']];$('#app').innerHTML=`<div class="shell learner-shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><p class="nav-label">MINHA TRILHA</p><nav class="nav" aria-label="Menu do aluno">${nav.map(([key,label,i])=>`<button data-learner-page="${key}" class="${learnerPage===key?'active':''}" ${learnerPage===key?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="profile profile-link" data-learner-page="profile">${personAvatar(studentPreview?{}:myProfile,p.student.name)}<div><strong>${esc(p.student.name)}</strong><span class="muted small">Aluno · Meu perfil</span></div>${icon('arrow')}</button>${studentPreview?'':btn('Sair','logout','text','logout')}</div></aside><main class="main"><header class="topbar"><span class="breadcrumb"><b>Minha Trilha &nbsp; / &nbsp; ${nav.find(n=>n[0]===learnerPage)?.[1]||'Perfil'}</b></span><span class="mobile-brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></span><div class="actions">${studentPreview?'<span class="pill">Prévia</span>':iconBtn('Atualizar meus dados','refresh-access','refresh')}<button class="learner-profile-button" data-learner-page="profile" aria-label="Meu perfil">${personAvatar(studentPreview?{}:myProfile,p.student.name)}</button></div></header><div class="content">${studentPreview?`<div class="preview-bar"><span>${icon('users')}Prévia de <strong>${esc(p.student.name)}</strong> · envios desativados</span>${btn('Voltar à coordenação','learner-exit','secondary','arrow')}</div>`:''}${studentPortals.length>1&&!studentPreview?`<label class="portal-selector">Minha turma<select id="portal-selector">${studentPortals.map((p,i)=>`<option value="${i}" ${i===portalIndex?'selected':''}>${esc(p.class_name)}</option>`).join('')}</select></label>`:''}${({home:learnerHome,learning:learnerLearning,grades:learnerGrades,attendance:learnerAttendance,finance:learnerFinance,notices:p=>heading('Avisos','Comunicados e orientações da coordenação.')+`<section class="panel">${p.notices.length?p.notices.map(learnerNotice).join(''):empty('Tudo em dia','Os avisos da sua turma aparecerão aqui.','','','bell')}</section>`,profile:learnerProfile}[learnerPage]||learnerHome)(p)}<footer class="footer"><span>Trilha Apostólica · Minha Trilha</span>${studentPreview?'':btn('Sair da conta','logout','text','logout')}</footer></div></main></div>`;bind();bindProfile();bindQuizzes();bindMaterialSearch();$$('[data-learner-page]').forEach(b=>b.onclick=()=>guardNavigation(()=>{navigateLearner(b.dataset.learnerPage)}));if($('#portal-selector'))$('#portal-selector').onchange=e=>{const index=Number(e.target.value);guardNavigation(()=>{portalIndex=index;workspaceId=studentPortals[index].owner_id;Promise.all([loadFinance(),loadQuizzes(),loadRecordedLessons()]).then(renderStudent).catch(e=>toast(friendly(e)))})}}
function openLearnerItem(id){const item=currentPortal()?.learning_items.find(i=>i.id===id&&i.kind==='material');if(!item)return;const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${esc(item.title)}</h2><span class="pill">Livro ou material de apoio</span><div class="learning-detail">${esc(item.body)}</div>${resourceURL(item.resource_url)?`<a class="btn secondary" href="${esc(resourceURL(item.resource_url))}" target="_blank" rel="noopener noreferrer">Abrir conteúdo ${icon('arrow')}</a>`:''}${item.due_date?``:''}<div class="form-actions"><button class="btn" id="close-learning">Fechar</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#close-learning').onclick=()=>d.close();d.showModal()}

function studentAdmin(){return heading('Área do aluno','Acesso individual e conteúdos para continuar aprendendo durante a semana.',btn('Novo conteúdo','learning-new','','plus'))+registrationPanel()+recordedLessonsAdmin()+`<section class="panel"><div class="panel-header"><h2>Veja como o aluno vai acessar</h2><span class="pill">Conta individual</span></div><div class="panel-body"><div class="portal-admin-access"><label>Aluno<select id="preview-student">${options(state.students.map(s=>({id:s.id,name:s.name})),previewStudentId,'Selecione um aluno')}</select></label><div class="actions">${btn('Abrir prévia','student-preview','secondary','users')}${btn('Vincular conta','student-link-selected','secondary','plus')}${btn('Copiar link de acesso','student-copy-link','secondary','arrow')}</div></div><p class="field-help">As pessoas podem criar a própria conta e confirmar o e-mail. Aprove as solicitações acima e vincule cada conta ao aluno correto.</p></div></section><section class="panel"><div class="panel-header"><h2>Materiais de apoio e histórico</h2><span class="pill">${learningItems.length} conteúdos</span></div><div class="panel-body">${learningItems.length?`<div class="admin-learning-list">${learningItems.map(i=>`<article class="admin-learning-item"><div><div class="actions"><span class="pill">${i.kind==='activity'?'Atividade antiga · histórico':'Material'}</span><span class="pill">${i.published?'Publicado':'Rascunho'}</span></div><h3>${esc(i.title)}</h3><p class="small muted">${esc(className(i.class_id))}${i.due_date?' · '+date(i.due_date):''}</p></div><div class="actions">${i.kind==='activity'?btn('Respostas','learning-responses:'+i.id,'secondary','grades'):''}${i.kind==='material'?iconBtn('Editar conteúdo','learning-edit:'+i.id,'edit'):''}${iconBtn('Excluir conteúdo','learning-delete:'+i.id,'trash')}</div></article>`).join('')}</div>`:empty('Aprender também durante a semana','Publique textos e links de apoio para cada turma. Crie as atividades na aba Quizzes.','learning-new','Criar conteúdo','book')}</div></section>`}
async function persistLearning(items){if(local()){if(localStorage.getItem(LEARNING_KEY)!==learningSnapshot)throw Error('Os conteúdos foram alterados em outra janela. Recarregue antes de salvar.');const raw=JSON.stringify(items);localStorage.setItem(LEARNING_KEY,raw);learningSnapshot=raw;learningItems=items}else await loadAdminLearning()}
function editLearning(id){if(!local()&&!portalReady){toast('Recurso indisponível. Atualize os dados e tente novamente.');return}if(!state.classes.length){toast('Cadastre uma turma antes de publicar conteúdos.');return}const item=learningItems.find(i=>i.id===id)||{};if(item.kind==='activity'){toast('Esta atividade está no histórico. Crie as novas atividades em Quizzes.');return}modal(item.id?'Editar conteúdo':'Novo conteúdo','Materiais de apoio para a turma. Para criar atividades, use Quizzes.',`<div class="form-grid"><label>Tipo<select name="kind"><option value="material">Material de apoio</option></select></label><label>Turma<select name="class_id" required>${options(state.classes,item.class_id)}</select></label><label class="full">Título<input name="title" required maxlength="120" value="${esc(item.title||'')}"></label><label class="full">Texto ou enunciado<textarea name="body" maxlength="10000" placeholder="Escreva o material de apoio…">${esc(item.body||'')}</textarea></label><label class="full">Link do livro ou material <span class="field-help">Opcional · PDF, vídeo, leitura ou outro recurso HTTPS</span><input name="resource_url" type="url" maxlength="2000" placeholder="https://…" value="${esc(item.resource_url||'')}"></label><label>Data sugerida <span class="field-help">Opcional</span><input name="due_date" type="date" value="${item.due_date||''}"></label><label>Visibilidade<select name="published"><option value="false">Rascunho</option><option value="true" ${item.published?'selected':''}>Publicado para a turma</option></select></label></div>`,async values=>{if(busy)return;const title=values.title.trim();if(!title)throw Error('Informe o título.');if(!state.classes.some(c=>c.id===values.class_id))throw Error('Selecione uma turma válida.');const link=values.resource_url.trim();if(link&&!resourceURL(link))throw Error('Use um link HTTPS válido.');const fields={kind:values.kind,class_id:values.class_id,title,body:values.body.trim(),resource_url:link?resourceURL(link):'',due_date:values.due_date||null,published:values.published==='true',updated_at:new Date().toISOString()};busy=true;try{if(local()){const record={...item,...fields,id:item.id||uid(),created_at:item.created_at||new Date().toISOString()};await persistLearning(item.id?learningItems.map(i=>i.id===item.id?record:i):[record,...learningItems])}else{const table=client.from('school_learning_items');const result=item.id?await table.update(fields).eq('id',item.id).eq('workspace_owner_id',workspaceId).select('id').single():await table.insert({workspace_owner_id:workspaceId,...fields}).select('id').single();if(result.error)throw result.error;await loadAdminLearning()}$('#modal').close();render();toast(fields.published?'Conteúdo publicado para a turma.':'Rascunho salvo.')}finally{busy=false}})}
function studentLinkDialog(id){const s=state.students.find(s=>s.id===id);if(!s){toast('Selecione um aluno.');return}if(local()||!portalReady){toast('Conecte o Supabase e execute a atualização da área do aluno para liberar contas.');return}const existing=studentLinks.find(l=>l.student_id===id);modal('Acesso de '+esc(s.name),'Vincule uma conta individual ao cadastro deste aluno.',`<label>E-mail do aluno<input name="email" type="email" required value="${esc(existing?.email||'')}" placeholder="aluno@exemplo.com"></label>${existing?btn('Remover vínculo atual','student-unlink:'+id,'danger','trash'):''}`,async values=>{const {error}=await client.rpc('school_link_student',{workspace_id:workspaceId,student_record_id:id,student_email:values.email.trim()});if(error)throw error;await loadAdminLearning();$('#modal').close();render();toast('Conta vinculada ao aluno.')})}
async function learningResponses(id){const i=learningItems.find(i=>i.id===id);if(!i)return;if(local()){toast('As respostas ficam disponíveis após conectar o Supabase.');return}try{const r=await client.from('school_learning_submissions').select('student_id,response,completed,updated_at').eq('workspace_owner_id',workspaceId).eq('item_id',id).order('updated_at',{ascending:false});if(r.error)throw r.error;const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Respostas</h2><p>${esc(i.title)} · participação opcional, sem nota.</p>${r.data.length?r.data.map(s=>`<article class="submission-card"><strong>${esc(state.students.find(x=>x.id===s.student_id)?.name||'Aluno sem cadastro atual')}</strong><span class="pill">${s.completed?'Concluída':'Em andamento'}</span><p>${esc(s.response||'Sem resposta escrita.')}</p><small class="muted">${new Date(s.updated_at).toLocaleString('pt-BR')}</small></article>`).join(''):empty('Nenhuma resposta por enquanto','As participações dos alunos serão exibidas aqui.','','','grades')}`;d.querySelector('.close').onclick=()=>d.close();d.showModal()}catch(e){toast(friendly(e))}}
async function copyStudentLink(){if(!local()&&!publicKey(config.key)){toast('Configure uma chave pública válida antes de copiar o link.');return}if(local()){toast('Conecte o Supabase antes de compartilhar o acesso.');return}const link=new URL(location.origin+location.pathname);if(!deploymentConfig)link.hash='acesso='+encodeURIComponent(JSON.stringify({url:config.url,key:config.key}));try{await navigator.clipboard.writeText(link.href);toast('Link copiado. Cada aluno entra com sua própria conta.')}catch{const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Link de acesso</h2><p>Compartilhe com os alunos autorizados. O link contém somente a configuração pública do projeto.</p><textarea readonly id="access-link">${esc(link.href)}</textarea>`;d.querySelector('.close').onclick=()=>d.close();d.showModal();$('#access-link').select()}}
function acceptAccessLink(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('acesso'))return false;try{const incoming=JSON.parse(params.get('acesso'));const u=new URL(incoming.url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash||!publicKey(incoming.key))throw Error('Configuração inválida.');if(deploymentConfig){if(u.origin!==deploymentConfig.url){$('#app').innerHTML=`<main class="lock panel"><h1>Este link é de outra Trilha</h1><p>Este endereço já possui uma conexão definida pela coordenação.</p><button class="btn" id="use-published-project">Entrar nesta Trilha</button></main>`;$('#use-published-project').onclick=()=>{history.replaceState(null,'',location.pathname+location.search);start()};return true}history.replaceState(null,'',location.pathname+location.search);return false}const apply=()=>{config={url:u.origin,key:incoming.key};localStorage.setItem(CONFIG,JSON.stringify(config));const registrationHint=uuidValue(params.get('inscricao'));history.replaceState(null,'',location.pathname+location.search+(registrationHint?'#inscricao='+registrationHint:''));location.reload()};if(config&&config.url===u.origin&&config.key===incoming.key){history.replaceState(null,'',location.pathname+location.search);return false}if(!config&&!localStorage.getItem(KEY)){apply();return true}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><h1>Acessar esta Trilha?</h1><p>Este link conecta ao projeto ${esc(u.hostname)}. Os registros locais serão preservados. Você entrará com sua própria conta.</p><div class="actions"><button class="btn" id="accept-access">Continuar</button><button class="btn secondary" id="cancel-access">Cancelar</button></div></main>`;$('#accept-access').onclick=apply;$('#cancel-access').onclick=()=>{history.replaceState(null,'',location.pathname+location.search);start()};return true}catch{$('#app').innerHTML='<main class="lock panel"><h1>Link inválido</h1><p>Peça à coordenação um novo link de acesso.</p></main>';return true}}
async function handleStudentAction(action){const [verb,id]=action.split(':');if(verb==='learner-tab'||verb==='learner-learning'){guardNavigation(()=>navigateLearner(verb==='learner-learning'?'learning':id,verb==='learner-learning'?id:undefined));return true}if(verb==='learner-item'){openLearnerItem(id);return true}if(verb==='learner-exit'){guardNavigation(()=>{studentPreview=false;page='student-area';render()});return true}if(verb==='student-preview'){const selected=$('#preview-student')?.value||id;if(!state.students.some(s=>s.id===selected)){toast('Selecione um aluno para abrir a prévia.');return true}previewStudentId=selected;studentPreview=true;learnerPage='home';renderStudent();return true}if(verb==='student-link-selected'){studentLinkDialog($('#preview-student')?.value);return true}if(verb==='student-link'){studentLinkDialog(id);return true}if(verb==='student-copy-link'){await copyStudentLink();return true}if(verb==='student-unlink'){const s=state.students.find(s=>s.id===id);$('#modal').close();confirmDialog('Remover acesso do aluno?',`${s?.name||'O aluno'} deixará de entrar nesta área. O cadastro e os registros serão preservados.`,async()=>{const {error}=await client.rpc('school_unlink_student',{workspace_id:workspaceId,student_record_id:id});if(error){toast(friendly(error));return}await loadAdminLearning();$('#modal').close();render();toast('Vínculo removido.')});return true}if(verb==='student-sql'){try{const r=await fetch('./student-area.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-area-do-aluno.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}return true}if(verb==='learning-new'||verb==='learning-edit'){guardNavigation(()=>editLearning(id));return true}if(verb==='learning-responses'){await learningResponses(id);return true}if(verb==='learning-delete'){confirmDialog('Excluir conteúdo?','O conteúdo e as respostas correspondentes serão excluídos. As notas das avaliações não serão alteradas.',async()=>{try{if(local())await persistLearning(learningItems.filter(i=>i.id!==id));else{const r=await client.from('school_learning_items').delete().eq('id',id).eq('workspace_owner_id',workspaceId);if(r.error)throw r.error;await loadAdminLearning()}$('#modal').close();render();toast('Conteúdo excluído.')}catch(e){toast(friendly(e))}});return true}return false}

async function loadIdentity(){
 if(local()){try{const p=JSON.parse(localStorage.getItem(PROFILE_KEY)||'null');if(p&&typeof p.display_name==='string')myProfile={...myProfile,...p}}catch{}return}
 const access=await client.rpc('school_access_context');
 if(access.error){if(!schemaMissing(access.error))throw databaseFailure(access.error,'identificar os acessos da sua conta');teamReady=false;workspaceId=session.user.id;return}
 teamReady=true;workspaces=access.data||[];
 if(!workspaces.length)await loadStudentIdentity();
 else{appRole='coordinator';const preferred=localStorage.getItem(workspacePreference());workspaceId=workspaces.find(w=>w.workspace_owner_id===preferred)?.workspace_owner_id||workspaces[0].workspace_owner_id;}
 if(appRole==='pending'){myProfile={display_name:pendingRegistration?.full_name||'',phone:'',responsibility:'',avatar_data:''};profileExists=false;return}
 const profile=await client.from('school_profiles').select('display_name,phone,responsibility,avatar_data').eq('user_id',session.user.id).maybeSingle();
 if(profile.error)throw databaseFailure(profile.error,'consultar seu perfil');
 profileExists=!!profile.data;
 myProfile=profile.data||{display_name:session.user.user_metadata?.full_name||'',phone:'',responsibility:'',avatar_data:''};
}
async function loadTeam(){if(local()||!teamReady){teamMembers=[];return}const {data,error}=await client.rpc('school_team_directory',{workspace_id:workspaceId});if(error)throw error;teamMembers=data||[]}
function profilePage(){
 avatarDraft=myProfile.avatar_data||'';
 const canEdit=local()||teamReady;
 return heading('Perfil','Seu perfil e as pessoas que cuidam da Trilha Apostólica.',local()?'':btn('Atualizar acesso','refresh-access','secondary','check'))+
 `<div class="profile-grid"><section class="panel"><div class="panel-header"><h2>Meu perfil</h2><span class="pill">${local()?'Perfil local':ownsWorkspace()?'Responsável principal':'Coordenador'}</span></div><div class="panel-body"><form id="profile-form"><fieldset ${canEdit?'':'disabled'}><div class="profile-photo-row"><div id="photo-preview">${personAvatar(myProfile,myName(),true)}</div><div><label class="btn secondary photo-label">Escolher foto<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button type="button" class="btn text" id="remove-photo">Remover foto</button><p class="field-help">JPG, PNG ou WebP · até 5 MB</p></div></div><div class="form-grid"><label class="full">Nome completo<input name="display_name" required maxlength="120" autocomplete="name" placeholder="Como você quer ser identificado?" value="${esc(myProfile.display_name)}"></label><label class="full">E-mail da conta<input type="email" readonly value="${esc(session?.user.email||'')}" placeholder="Disponível ao conectar sua conta"><span class="field-help">Usado para entrar no aplicativo.</span></label><label>Telefone <span class="field-help">Opcional</span><input name="phone" type="tel" autocomplete="tel" maxlength="30" value="${esc(myProfile.phone)}" placeholder="(00) 00000-0000"></label><label>Responsabilidade <span class="field-help">Opcional</span><input name="responsibility" maxlength="120" value="${esc(myProfile.responsibility)}" placeholder="Ex.: Coordenação pedagógica"></label></div><p class="form-error" id="profile-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">${icon('check')}Salvar perfil</button></div></fieldset></form>${local()?'<div class="note">Este perfil está salvo apenas neste navegador. Conecte sua conta para ter um perfil pessoal e participar da equipe.</div>':!teamReady?'':''}</div></section>
 <div><section class="panel"><div class="panel-header"><h2>Equipe de coordenação</h2>${teamReady&&ownsWorkspace()?btn('Adicionar','add-coordinator','secondary','plus'):''}</div>${local()?empty('Cada coordenador com sua conta','Conecte o Supabase e autorize a equipe para compartilhar turmas, notas e presenças.','go-settings','Configurar acesso','users'):!teamReady?empty('Equipe indisponível','Atualize os dados e tente novamente.','','','users'):`<div class="panel-body team-summary">${workspaces.length>1?`<label>Equipe em uso<select id="workspace-selector">${workspaces.map(w=>`<option value="${esc(w.workspace_owner_id)}" ${w.workspace_owner_id===workspaceId?'selected':''}>${esc(w.owner_name)}${w.is_owner?' · Minha equipe':''}</option>`).join('')}</select></label>`:''}</div><div class="team-list">${teamMembers.map(m=>`<article class="team-member"><span class="avatar">${esc(initials(m.display_name))}</span><div class="member-info"><strong>${esc(m.display_name)} ${m.user_id===session.user.id?'<span class="muted small">(você)</span>':''}</strong><span>${esc(m.email)}</span><span class="pill">${m.member_role==='owner'?'Responsável principal':'Coordenador'}</span></div>${ownsWorkspace()&&m.member_role!=='owner'?iconBtn('Remover acesso de '+esc(m.display_name),'remove-coordinator:'+m.user_id,'trash'):''}</article>`).join('')}</div><div class="panel-body"><p class="field-help">Cada pessoa entra com sua própria conta. Use a mesma URL e chave pública do Supabase em cada dispositivo. Também é necessário liberar o acesso a este endereço para cada coordenador.</p></div>`}</section><section class="panel"><div class="panel-header"><h2>Minha conta</h2></div><div class="panel-body"><div class="info-line"><span>Acesso</span><strong>${local()?'Neste dispositivo':'Conta individual'}</strong></div><div class="info-line"><span>Dados da escola</span><strong>${local()?'Locais':teamReady?'Equipe compartilhada':'Seu espaço atual'}</strong></div>${local()?'':btn('Sair da conta','logout','secondary','logout')}</div></section></div></div>`;
}
async function preparePhoto(file){
 if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha uma foto JPG, PNG ou WebP.');
 if(file.size>5*1024*1024)throw Error('A foto deve ter no máximo 5 MB.');
 const objectURL=URL.createObjectURL(file);
 try{const image=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Não foi possível abrir essa foto.'));im.src=objectURL});const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const side=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,256,256);const data=canvas.toDataURL('image/jpeg',.78);if(!safePhoto(data))throw Error('A foto é muito detalhada. Tente outra imagem.');return data}finally{URL.revokeObjectURL(objectURL)}
}
function photoPreview(){const name=$('#profile-form [name="display_name"]')?.value||myName();$('#photo-preview').innerHTML=personAvatar({avatar_data:avatarDraft},name,true)}
async function storeOnlineProfile(profile){
 const fields={...profile,updated_at:new Date().toISOString()};
 const table=()=>client.from('school_profiles');
 // The account ID is used only when creating a profile; it is never updated.
 let result=await (profileExists?table().update(fields).eq('user_id',session.user.id):table().insert({user_id:session.user.id,...fields})).select('user_id').single();
 // A second tab may have created the profile after it was loaded here.
 if(result.error?.code==='23505')result=await table().update(fields).eq('user_id',session.user.id).select('user_id').single();
 if(result.error)throw result.error;
 profileExists=true;
}
function bindProfile(){
 if(!$('#profile-form'))return;
 $('#profile-form').oninput=()=>dirty=true;
 $('#profile-photo').onchange=async e=>{const input=e.target;input.disabled=true;const submit=$('#profile-form button[type="submit"]');submit.disabled=true;try{const photo=await preparePhoto(input.files[0]);if(photo){avatarDraft=photo;dirty=true;photoPreview()}}catch(e){$('#profile-error').textContent=friendly(e)}finally{input.disabled=false;submit.disabled=false;input.value=''}};
 $('#remove-photo').onclick=()=>{avatarDraft='';dirty=true;photoPreview()};
 $('#profile-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget;if(!form.reportValidity())return;const fields=new FormData(form);const profile={display_name:fields.get('display_name').trim(),phone:fields.get('phone').trim(),responsibility:fields.get('responsibility').trim(),avatar_data:avatarDraft};if(!profile.display_name){$('#profile-error').textContent='Informe seu nome.';return}busy=true;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;$('#profile-error').textContent='';try{if(local())localStorage.setItem(PROFILE_KEY,JSON.stringify(profile));else{if(!teamReady)throw Error('Execute a atualização SQL antes de salvar seu perfil.');await storeOnlineProfile(profile)}myProfile=profile;teamMembers=teamMembers.map(m=>m.user_id===session?.user.id?{...m,display_name:profile.display_name}:m);dirty=false;render();toast('Perfil salvo.')}catch(error){$('#profile-error').textContent=friendly(error)}finally{busy=false;submit.disabled=false}};
 if($('#workspace-selector'))$('#workspace-selector').onchange=e=>{const selected=e.target.value;if(!workspaces.some(w=>w.workspace_owner_id===selected))return;guardNavigation(()=>{localStorage.setItem(workspacePreference(),selected);location.reload()});if(dirty)e.target.value=workspaceId};
}
function addCoordinator(){if(!teamReady||!ownsWorkspace())return;modal('Adicionar coordenador','Libere o acesso de uma conta existente às mesmas turmas, notas e presenças da sua equipe.',`<label>E-mail do coordenador<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="nome@exemplo.com"></label>`,async values=>{const {error}=await client.rpc('school_add_coordinator',{workspace_id:workspaceId,member_email:values.email.trim()});if(error)throw error;await loadTeam();$('#modal').close();render();toast('Coordenador adicionado à equipe.')})}
function removeCoordinator(id){if(!ownsWorkspace()||id===session.user.id)return;const member=teamMembers.find(m=>m.user_id===id);if(!member)return;confirmDialog('Remover acesso da equipe?',`${member.display_name} deixará de acessar os dados desta equipe. A conta e os registros dos alunos serão preservados.`,async()=>{const {error}=await client.rpc('school_remove_coordinator',{workspace_id:workspaceId,member_id:id});if(error){toast(friendly(error));return}await loadTeam();$('#modal').close();render();toast('Acesso à equipe removido.')})}
async function downloadTeamSQL(){try{const r=await fetch('./profiles-team.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-perfis-e-equipe.sql',await r.text(),'text/plain')}catch(e){toast('Não foi possível baixar a atualização: '+friendly(e))}}
async function refreshAccess(){guardNavigation(async()=>{const wasPending=appRole==='pending';try{await load();render();toast(appRole==='pending'?'Sua solicitação continua aguardando a conferência da coordenação.':wasPending&&appRole==='student'?'Acesso liberado. Bem-vindo à Trilha!':'Dados e acesso atualizados.')}catch(e){if(!session&&!local()){renderLogin(friendly(e));return}if(appRole==='student')renderStudent();else if(appRole==='pending')renderPending();toast((wasPending&&appRole==='student'?'Seu acesso foi liberado. ':'')+friendly(e))}})}
function moreMenu(){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Mais opções</h2><nav class="more-nav" aria-label="Mais opções">${[['classes','Turmas','book'],['notices','Avisos','bell'],['reports','Acompanhamento','chart'],['student-area','Área do aluno','users'],['quizzes','Quizzes','trophy'],['finance','Financeiro','wallet'],['settings','Configurações','settings']].map(([id,label,i])=>`<button class="btn secondary" data-target="${id}">${icon(i)}${label}${icon('arrow')}</button>`).join('')}</nav>`;d.querySelector('.close').onclick=()=>d.close();d.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{d.close();guardNavigation(()=>{page=b.dataset.target;viewClass='';search='';render();window.scrollTo(0,0)})});d.showModal()}

async function load(){
 await syncAuthSession();
 await loadIdentity();
 if(appRole==='pending'){state=fresh();revision=null;financeCharges=[];loaded=true;return}
 if(appRole==='student'){state=fresh();revision=null;await loadFinance();await loadQuizzes();await loadRecordedLessons();loaded=true;return}
 if(local()){const raw=localStorage.getItem(KEY);localSnapshot=raw;if(raw){const v=JSON.parse(raw);if(!validState(v))throw Error('O arquivo local está inválido. Preserve uma cópia antes de continuar.');state=v}else state=fresh();await loadAdminLearning();await loadFinance();await loadQuizzes();await loadRecordedLessons();loaded=true;return}
 const {data,error}=await client.from('school_workspaces').select('data,revision').eq('owner_id',workspaceId).maybeSingle();if(error)throw databaseFailure(error,'consultar os dados da coordenação');
 if(data){if(!validState(data.data))throw Error('Formato de dados não reconhecido.');state=data.data;revision=data.revision}
 else{const res=await client.from('school_workspaces').insert({owner_id:workspaceId,data:fresh(),revision:1}).select('data,revision').single();if(res.error)throw databaseFailure(res.error,'iniciar os dados da coordenação');state=res.data.data;revision=res.data.revision}
 await loadTeam();
 await loadAdminLearning();
 await loadFinance();
 await loadRegistration();
 await loadQuizzes();
 await loadRecordedLessons();
 loaded=true;
}
async function save(next,message='Salvo com sucesso.'){
 if(appRole==='student'||appRole==='pending'){toast('Esta operação é exclusiva da coordenação.');return false}
 if(busy)return false;busy=true;$$('button[type="submit"], [data-action="save-grades"], [data-action="save-attendance"]').forEach(b=>b.disabled=true);
 try{
  if(!validState(next))throw Error('Os dados não passaram pela validação.');
  if(local()){if(localStorage.getItem(KEY)!==localSnapshot)throw Error('Os dados foram alterados em outra janela. Exporte a cópia e recarregue antes de salvar.');const serialized=JSON.stringify(next);localStorage.setItem(KEY,serialized);localSnapshot=serialized;}
  else{if(!session||revision===null)throw Error('Entre na sua conta para salvar.');const {data,error}=await client.from('school_workspaces').update({data:next,revision:revision+1,updated_at:new Date().toISOString()}).eq('owner_id',workspaceId).eq('revision',revision).select('revision').maybeSingle();if(error)throw error;if(!data)throw Error('Outra janela ou outro coordenador alterou os dados. Recarregue os registros antes de tentar salvar novamente.');revision=data.revision}
  state=next;dirty=false;toast(message);return true;
 }catch(e){toast('Não foi possível salvar: '+friendly(e));return false}finally{busy=false;$$('button:disabled').forEach(b=>b.disabled=false)}
}
function friendly(e){const msg=e.message||String(e);if(/Invalid login credentials/.test(msg))return 'E-mail ou senha incorretos.';if(/Failed to fetch|fetch failed/.test(msg))return 'Confira a conexão com a internet e a configuração do Supabase.';if(/row-level security|permission denied/.test(msg)){const object=msg.match(/permission denied for (?:table|function|schema|relation) [A-Za-z0-9_.]+/i)?.[0];return 'O banco bloqueou '+(e.operationLabel||'esta operação')+(e.code?' (código '+e.code+')':'')+'.'+(object?' Detalhe: '+object+'.':' Verifique a autorização da conta e a atualização SQL.')}return msg}
const className=id=>state.classes.find(c=>c.id===id)?.name||'Sem turma';
const studentsFor=id=>state.students.filter(s=>!id||s.classId===id).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
const studentMean=id=>{const gs=state.grades.filter(g=>g.studentId===id);return gs.length?gs.reduce((n,g)=>n+Number(g.value),0)/gs.length:null};
const frequency=id=>{const a=state.attendance.filter(a=>a.studentId===id&&a.status!=='excused');return a.length?a.filter(a=>a.status==='present').length/a.length*100:null};
const avatar=name=>`<span class="avatar">${esc(initials(name))}</span>`;
function options(items,selected,empty='Selecione'){return `<option value="">${empty}</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.title)}</option>`).join('')}
function empty(title,body,action='',label='',i='book'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${body}</p>${action?btn(label,action,'', 'plus'):''}</div>`}
function heading(title,desc,actions=''){return `<div class="heading"><div><h1>${title}</h1></div><div class="actions">${actions}</div></div>`}
function stat(label,value,sub,i){return `<article class="stat"><div class="stat-head">${label}<span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong><small>${sub}</small></article>`}
